const CELL_CAPS: Record<ImportKind, number[]> = {
  contacts: [MAX_EMAIL_LENGTH, MAX_CONTACT_NAME, 400, 40],
  products: [MAX_TITLE_LENGTH, 30, MAX_ABOUT_LENGTH * 2, 20, 2_000],
