/**
 * What the public API hands out, and in what shape.
 *
 * Every object here is built field by field from a list written out below —
 * never by spreading a stored record. Stored records carry things that must
 * never leave: a contact's unsubscribe token, a member's internal flags, an
 * affiliate's private note. A field added to a record later stays inside
 * until somebody decides, here, in writing, that it goes out.
 *
 * Each reader is the one the studio already uses for the same list, so the
 * API can never show a creator something different from what their own
 * dashboard shows them.
 *
 * Every time goes out as an ISO 8601 string in UTC, whatever it was kept as —
 * seconds for members and students, milliseconds for bookings and
 * affiliates, text already for contacts — so no tool has to guess the unit.
 */
import { apiError } from "@/lib/api-guard";
import { isRedisConfigured, redisPipeline } from "@/lib/redis";
import { UnknownReplyError, countOf, repliesFor, stringList } from "@/lib/redis-reply";
import type { Store } from "@/lib/store";
import { productIds, readListing, readListings } from "@/lib/catalog";
import { listingsToRead } from "@/lib/catalog-read-count";
import { leadsKey, parseContact } from "@/lib/contacts";
import { memberPage } from "@/lib/community";
import { readCourse } from "@/lib/course";
import { studentPage } from "@/lib/learn";
import { BOOK_STRIPE_PAGES, bookSizes, readBook } from "@/lib/affiliates";
import { paidCalls } from "@/lib/calls";
import { productLink } from "@/lib/checkout-recovery";
import {
  type ReadWork, API_PAGE_ROWS, addWork, apiReadUnits, bookWork, bookingsWork, EVENTS_PROBE_MOST, eventsSentMost, eventsWork, listPageMost, numbersWork, productsPageWork, scannedPageWork, settledUnits,
  studentsPageWork,
} from "@/lib/api-read-rules";
import { type WebhookEvent, deliveryReadBound, recentDeliverySizes, recentLimit, recentMessagesOf } from "@/lib/webhooks";
import { readsSales } from "@/lib/stats";
import { paypalCounts } from "@/lib/paypal-sales";

export type Page<T> = { data: T[]; next: string | null };

/** How many rows one page of a long list holds. */
export const API_PAGE = API_PAGE_ROWS;

/**
 * Takes `more` of the store's API requests before a reading that costs more
 * than its request (lib/api-guard.ts, takeMoreApi): null when taken, else the
 * refusal to send as it is. `taken` is what the same reading already took,
 * when this is a later step of it (its refusal says so). Every reader below
 * past the door takes what it reads before it reads it.
 */
export type Charge = (more: number, taken?: number) => Promise<Response | null>;

/**
 * Sets `most` aside before a reading whose size is known only once read, and
 * hands back how to settle it at what it really took (lib/api-guard.ts,
 * holdMoreApi), or the refusal, with nothing read.
 */
export type Hold = (most: number) => Promise<Response | ((actual: number) => Promise<Response | null>)>;

/** Every field each list's rows go out with, so a field asked for is checked before anything is taken or read (lib/api-fields.ts, badFields). */
export const PRODUCT_FIELDS = ["id", "title", "price", "currency", "kind", "interval", "hidden", "url"] as const;
export const LEAD_FIELDS = ["email", "name", "agreed", "agreed_at", "unsubscribed", "unsubscribed_at", "first_at", "last_at", "products", "product_ids", "tags", "source"] as const;
export const MEMBER_FIELDS = ["email", "name", "handle", "listed", "announcements", "muted", "removed", "joined_at", "last_seen_at"] as const;
export const STUDENT_FIELDS = ["email", "lessons_done", "lessons_total", "started_at", "last_seen_at", "blocked"] as const;
export const AFFILIATE_FIELDS = ["id", "email", "code", "status", "applied_at", "clicks", "sales", "earned", "paid", "owed", "payable", "waiting"] as const;
export const BOOKING_FIELDS = ["id", "product_id", "title", "email", "name", "starts_at", "ends_at", "buyer_time_zone", "moved", "amount", "currency", "answers"] as const;

/** Bytes as sent. */
const sentBytes = (value: unknown) => Buffer.byteLength(JSON.stringify(value));

const isoFromSeconds = (s: number) => (s > 0 ? new Date(s * 1000).toISOString() : null);
const isoFromMs = (ms: number) => (ms > 0 ? new Date(ms).toISOString() : null);
const isoFromText = (t: string) => {
  if (!t) return null;
  const at = Date.parse(t);
  return Number.isFinite(at) ? new Date(at).toISOString() : null;
};

/** The store itself: enough for a tool to know which store a key reads. */
export function storeInfo(store: Store) {
  return { handle: store.handle, name: store.name, currency: store.currency };
}

/**
 * Every product, in the creator's order, a page at a time. What reading the
 * page's listings costs is taken first, counted from the listings the store's
 * own record does not hold (lib/api-read-rules.ts, productsPageWork).
 */
export async function products(store: Store, cursor: string | null, charge: Charge): Promise<Page<Record<string, unknown>> | Response> {
  // The order is in the store's own index, so only the page asked for is
  // read. It used to read the whole catalogue to answer for twenty of it.
  const ids = productIds(store);
  const from = cursor && /^\d{1,6}$/.test(cursor) ? Number(cursor) : 0;
  const page = ids.slice(from, from + API_PAGE);
  const refused = await charge(apiReadUnits(productsPageWork(page.length, listingsToRead(store, page))));
  if (refused) return refused;
  const slice = await readListings(store, page);
  return {
    data: slice.map((p) => ({
      id: p.id,
      title: p.title,
      price: p.priceCents,
      currency: store.currency,
      kind: p.call ? "call" : p.course ? "course" : p.recurring ? "membership" : p.priceCents === 0 ? "free" : "one_time",
      interval: p.recurring?.interval ?? null,
      hidden: p.hidden === true,
      url: productLink(store, p.id),
    })),
    next: from + API_PAGE < ids.length ? String(from + API_PAGE) : null,
  };
}

/**
 * The creator's list: everybody who asked for something free, bought, or was
 * brought in by an import. The same rows the studio's CSV export writes, in
 * the same order Redis keeps them. `agreed=true` narrows it to those who
 * agreed to hear from the creator and have not left.
 */
export async function leads(store: Store, cursor: string | null, onlyAgreed: boolean): Promise<LeadsPage> {
  return (await scanLeads(store, cursor, onlyAgreed)).page;
}

/**
 * leads, paid for first: a page at its most (listPageMost) is set aside
 * before the scan, so a store without the requests it may take reads
 * nothing; then it is settled at what the scan read and what is sent
 * (scannedPageWork), before it is sent. The refusal, as it is, when it is
 * not left. What /api/v1/leads answers.
 */
export async function chargedLeads(store: Store, cursor: string | null, onlyAgreed: boolean, hold: Hold): Promise<LeadsPage | Response> {
  if (!store.listId || !isRedisConfigured()) return { data: [], next: null };
  return scannedPage(hold, listPageMost("leads", API_PAGE), async () => {
    const { page, readBytes } = await scanLeads(store, cursor, onlyAgreed);
    return { out: page, work: scannedPageWork(1, readBytes, sentBytes(page)) };
  });
}

/**
 * The store's recent messages of one event (GET /api/v1/events), paid for by
 * what they really are, each part before it is done (Codex G2, #2192):
 *   1. the measuring at its most (EVENTS_PROBE_MOST) is set aside before the
 *      log is read, so a store without it measures nothing;
 *   2. the log and the size of each delivery in it are looked up
 *      (recentDeliverySizes), and the rest of the reading is set aside at
 *      each delivery's bound (deliveryReadBound: what its tries may still
 *      write on it) and the most that can be sent of them;
 *   3. they are read, each only up to its bound (recentMessagesOf), and the
 *      whole is settled at the bytes read and sent (eventsWork), before they
 *      are sent.
 * The refusal, as it is, when a part is not left, with nothing of it done.
 * Measuring or reading that cannot be confirmed keeps what was set aside.
 */
export async function recentEvents(store: Store, type: WebhookEvent, limit: number, hold: Hold): Promise<Record<string, unknown>[] | Response> {
  const probeHeld = apiReadUnits(EVENTS_PROBE_MOST);
  const settleProbe = await hold(probeHeld);
  if (settleProbe instanceof Response) return settleProbe;
  const sized = await recentDeliverySizes(store);
  if (!sized) throw new Error("the recent deliveries could not be measured");
  const most = recentLimit(limit);
  const bounds = sized.sizes.map(deliveryReadBound);
  const whole = apiReadUnits(eventsWork({ deliveries: sized.ids.length, bytes: sized.logBytes + bounds.reduce((n, b) => n + b, 0), sent: eventsSentMost(bounds, most) }));
  // What the measuring already set aside counts toward the whole; only the rest is taken now.
  const restHeld = Math.max(0, whole - probeHeld);
  const settleRest = await hold(restHeld);
  if (settleRest instanceof Response) {
    // Nothing more is read: the measuring done is settled at what it was.
    await settleProbe(settledUnits({ commands: 1 + sized.ids.length, bytes: sized.logBytes, roundTrips: sized.ids.length ? 2 : 1 }, probeHeld));
    // Said with the whole the reading may take, not only the rest of it.
    const words = settleRest.status === 429 ? ((await settleRest.clone().json().catch(() => null)) as { error?: string } | null) : null;
    return words?.error === "monthly_limit"
      ? apiError(429, "monthly_limit", `This read may take up to ${(whole + 1).toLocaleString("en-US")} of your store's API requests, more than your store has left, so no event was read. The requests used to measure them stay counted.`)
      : settleRest;
  }
  const { messages, readBytes } = await recentMessagesOf(store, type, sized.ids, bounds, most);
  const due = settledUnits(eventsWork({ deliveries: sized.ids.length, bytes: sized.logBytes + readBytes, sent: sentBytes(messages) }), probeHeld + restHeld);
  // The whole is settled across the two: the measuring's part first, the rest after.
  const refusedProbe = await settleProbe(Math.min(due, probeHeld));
  const refused = await settleRest(Math.max(0, due - probeHeld));
  return refusedProbe ?? refused ?? messages;
}

/** A page set aside at `most`, read, and settled at what it did before it is sent (lib/api-guard.ts, holdMoreApi). */
async function scannedPage<T>(hold: Hold, most: ReadWork, read: () => Promise<{ out: T; work: ReadWork }>): Promise<T | Response> {
  const held = apiReadUnits(most);
  const settle = await hold(held);
  if (settle instanceof Response) return settle;
  const { out, work } = await read();
  const refused = await settle(settledUnits(work, held));
  return refused ?? out;
}

/** A page of the list, with how many contacts it holds that could not be read (only when there are any): never left out without a word (rule 24). */
type LeadsPage = Page<Record<string, unknown>> & { unreadable?: number };

async function scanLeads(store: Store, cursor: string | null, onlyAgreed: boolean): Promise<{ page: LeadsPage; readBytes: number }> {
  if (!store.listId || !isRedisConfigured()) return { page: { data: [], next: null }, readBytes: 0 };
  const start = cursor && /^\d{1,20}$/.test(cursor) ? cursor : "0";
  // HSCAN answers [cursor, [field, value, ...]] (CX-123 rule 24): a page in any other shape is unknown, never a
  // last or empty page, so a sync is never told it has the whole list when it has part of it (502 in the route).
  const reply = repliesFor(repliesFor(await redisPipeline([["HSCAN", leadsKey(store.listId), start, "COUNT", API_PAGE]]), 1)?.[0], 2);
  const cursorReply = reply?.[0];
  const next = typeof cursorReply === "string" && /^\d{1,20}$/.test(cursorReply) ? cursorReply : countOf(cursorReply) !== null ? String(cursorReply) : null;
  const flat = stringList(reply?.[1]);
  if (next === null || !flat || flat.length % 2 !== 0) throw new UnknownReplyError("a page of a store's list");
  const data: Record<string, unknown>[] = [];
  let unreadable = 0;
  for (let i = 0; i + 1 < flat.length; i += 2) {
    const c = parseContact(flat[i + 1]);
    if (!c) {
      unreadable += 1;
      continue;
    }
    const mailable = c.agreed && !c.unsub;
    if (onlyAgreed && !mailable) continue;
    data.push({
      email: flat[i],
      name: c.name || null,
      agreed: c.agreed,
      agreed_at: isoFromText(c.agreedAt),
      unsubscribed: c.unsub,
      unsubscribed_at: isoFromText(c.unsubAt),
      first_at: isoFromText(c.firstAt),
      last_at: isoFromText(c.lastAt),
      products: c.titles,
      product_ids: c.ids,
      tags: c.tags,
      source: c.source || null,
    });
  }
  // The bytes the scan answered with, for the reading that pays for them (chargedLeads).
  const readBytes = flat.reduce((n, v) => n + Buffer.byteLength(v), 0);
  return { page: { data, next: next === "0" ? null : next, ...(unreadable ? { unreadable } : {}) }, readBytes };
}

/**
 * The community's members, as the creator's own member list shows them: a
 * page at its most set aside before the scan, settled at what it read and
 * sends before anything is sent, as the list's.
 */
export async function members(store: Store, cursor: string | null, hold: Hold): Promise<Page<Record<string, unknown>> | Response> {
  const id = store.community?.id;
  if (!id) return { data: [], next: null };
  const start = cursor && /^\d{1,20}$/.test(cursor) ? cursor : "0";
  return scannedPage(hold, listPageMost("members", API_PAGE), async () => {
    const page = await memberPage(id, start, API_PAGE);
    const out = {
      data: page.members.map((m) => ({
        email: m.e,
        name: m.n || null,
        handle: m.h || null,
        listed: m.dir && Boolean(m.n),
        announcements: m.mail,
        muted: m.muted,
        removed: m.removed,
        joined_at: isoFromSeconds(m.at),
        last_seen_at: isoFromSeconds(m.seen),
      })),
      next: page.next === "0" ? null : page.next,
    };
    return { out, work: scannedPageWork(2, page.bytes, sentBytes(out)) };
  });
}

/**
 * Everybody who has opened one course, with how far they got, a page at a
 * time in the order Redis keeps them. The page is read first; what each of
 * its students marked done is read only once the further requests that costs
 * are taken (lib/api-read-rules.ts, studentsPageWork), so a course of any size
 * costs by the page and never by the whole course at once.
 */
export async function students(
  store: Store,
  productId: string,
  cursor: string | null,
  charge: Charge,
): Promise<{ data: Record<string, unknown>[]; total: number; next: string | null } | Response | null> {
  // One product by id, which is one read — not every product in the store.
  const product = await readListing(store, productId);
  if (!product?.course) return null;
  const course = await readCourse(product.course.id);
  if (!course) return null;
  const lessons = course.modules.reduce((n, m) => n + m.lessons.length, 0);
  const start = cursor && /^\d{1,20}$/.test(cursor) ? cursor : "0";
  // What the charge said, kept outside the callback that asks it.
  const said: { refused: Response | null } = { refused: null };
  const page = await studentPage(course, start, API_PAGE, async (rows, blocked) => {
    said.refused = await charge(apiReadUnits(studentsPageWork(rows, blocked)));
    return said.refused === null;
  });
  if (said.refused) return said.refused;
  if (!page) throw new Error("the course's students could not be counted");
  return {
    total: page.total,
    data: page.students.map((s) => ({
      email: s.email,
      lessons_done: s.done,
      lessons_total: lessons,
      started_at: isoFromSeconds(s.since),
      last_seen_at: isoFromSeconds(s.lastSeen),
      blocked: s.blocked,
    })),
    next: page.next === "0" ? null : page.next,
  };
}

/**
 * The further API requests one reading of the affiliate program takes, from
 * its size counted just before (lib/affiliates.ts, bookSizes), taken before it
 * is read: null when taken, else the refusal. Shared with the MCP tool
 * (lib/mcp-tools.ts, affiliatesTool), which reads the same book.
 */
export async function chargeBook(store: Store, charge: Charge): Promise<Response | null> {
  const sizes = await bookSizes(store);
  if (!sizes) throw new Error("the affiliate program could not be counted");
  return charge(apiReadUnits(bookWork(sizes, BOOK_STRIPE_PAGES)));
}

/** Every affiliate, with what they have earned, been paid, and are owed. */
export async function affiliates(store: Store, charge: Charge): Promise<{ data: Record<string, unknown>[]; currency: string; refunds_checked: boolean } | Response> {
  const refused = await chargeBook(store, charge);
  if (refused) return refused;
  const book = await readBook(store);
  return {
    currency: book.currency,
    // When Stripe could not be asked about refunds, the amounts may be high.
    // Said, so a tool paying from these numbers can wait for a clean read.
    refunds_checked: book.refundsChecked,
    data: book.rows.map((r) => ({
      id: r.affiliate.id,
      email: r.affiliate.email,
      code: r.affiliate.code,
      status: r.affiliate.status,
      applied_at: isoFromMs(r.affiliate.appliedAt),
      clicks: r.clicks,
      sales: r.sales,
      earned: r.earned,
      paid: r.paid,
      owed: r.owed,
      payable: r.payable,
      waiting: r.waiting,
    })),
  };
}

/**
 * The further API requests one reading of the numbers takes (lib/stats-report.ts
 * readNumbers, and lib/mcp-tools.ts readFullNumbers before its listings), sized
 * first by the PayPal sales and refunds kept (lib/api-read-rules.ts,
 * numbersWork), for lib/api-numbers.ts to take before anything else is read.
 * `also` is work the same reading does with it, taken in the same go
 * (keeping a copy of them).
 */
export async function numbersUnits(store: Store, also: Partial<ReadWork> = {}): Promise<number> {
  const kept = Boolean(store.statsId);
  const sales = readsSales(store);
  const paypal = kept && sales ? await paypalCounts(store.statsId) : { sales: 0, refunds: 0 };
  if (!paypal) throw new Error("the PayPal sales could not be counted");
  const work = numbersWork({ kept, sales, stripe: Boolean(store.stripeAccountId), paypalSales: paypal.sales, paypalRefunds: paypal.refunds });
  return apiReadUnits(kept ? addWork(work, also) : work);
}

/**
 * Paid calls and session seats, each at the time it is booked for now. How
 * many there are is known only once Stripe has answered, so the further
 * requests its most (lib/api-read-rules.ts, bookingsWork) are taken before;
 * a store without Stripe connected reads nothing and takes none.
 */
export async function bookings(store: Store, charge: Charge): Promise<Record<string, unknown>[] | Response> {
  const refused = await charge(apiReadUnits(bookingsWork(Boolean(store.stripeAccountId))));
  if (refused) return refused;
  const rows = await paidCalls(store);
  return rows.map((c) => ({
    id: c.session,
    product_id: c.product,
    title: c.title,
    email: c.email,
    name: c.name,
    starts_at: isoFromMs(c.start),
    ends_at: isoFromMs(c.end),
    buyer_time_zone: c.buyerTz,
    moved: c.moves,
    amount: c.amount,
    // The currency it was paid in; the store's when the checkout said none.
    currency: c.currency || store.currency,
    answers: c.answers,
  }));
}

lib/api-read-rules.ts.content:
/**
 * How many of a store's API requests a reading takes when it reads more than
 * one request's worth (lib/api-read.ts, lib/mcp-tools.ts).
 *
 * A request is one of the store's monthly figure, priced at a light request:
 * the key, the store and the answer (tests/plan-cost-registry.ts, UNIT_COST.api),
 * and nothing more. Every reading past the door takes, on top, the further
 * requests its work below adds up to, and is refused with 429 when they are
 * not left: a page of products (its listings), of the list or of the members
 * (set aside at its most before the scan, settled at its rows as they came
 * back, before they are sent), a course's
 * students (each one's progress), the affiliates (the whole program and pages
 * of the creator's Stripe account), the bookings (up to five pages of it and
 * every booking's move, a hundred at an MGET), the numbers (ninety days of counts and up to
 * NUMBERS_STRIPE_PAGES pages of sales, renewals, refunds and disputes), the
 * memberships, the emails and what they sold, the recent events and the
 * discount codes. Whatever can be counted first (the program, the PayPal
 * sales and refunds, the listings a page needs, the emails' records, a kept
 * copy's size) is counted first; what cannot is taken at its most, or set
 * aside at its most and settled once measured (lib/api-guard.ts,
 * holdMoreApi). A store's own record, the key and the answer's envelope are
 * the door's.
 *
 * One further request pays for at most one of these, in any mix that adds up
 * to one: API_UNIT_COMMANDS database commands, API_UNIT_BYTES bytes read from
 * the database, API_UNIT_SENT_BYTES bytes sent to the caller, API_UNIT_STRIPE_PAGES
 * pages of a Stripe list waited on, API_UNIT_ROUND_TRIPS trips to the database
 * waited on one after another. tests/plan-cost-registry.test.ts holds each
 * figure under a request's price and every reading's units above its cost at
 * every size. Pure: no reads here.
 */
import { MAX_BODY_LENGTH, MAX_LESSONS } from "@/lib/course";
import { MAX_ABOUT_LENGTH } from "@/lib/product-about";
import { MAX_BLOCKS, MAX_STORED_PAGE_BYTES } from "@/lib/sales-page";
import { MAX_VERSIONS } from "@/lib/sales-page-store";
import { MAX_CHOICES, MAX_CHOICE_LENGTH, MAX_EXPLANATION_LENGTH, MAX_QUESTIONS, MAX_QUESTION_LENGTH } from "@/lib/quiz";
import { MAX_TASK_PROMPT } from "@/lib/assignment-rules";
import { DEPTH_RECORD_BYTES } from "@/lib/page-depth-rules";
import { MAX_SECTION_BYTES, MAX_SECTION_NAME } from "@/lib/saved-blocks";
import { SHARE_LIMITS } from "@/lib/funnel-share-rules";
import { DAY_FIELDS_MAX, LIFE_WRITE_MAX, STATS_DAYS } from "@/lib/stats";
import { DELIVERY_MAX_BYTES, LOG_SIZE, READ_DELIVERIES_CALLS_EACH, RECENT_MESSAGES_MAX } from "@/lib/webhooks";
import { MAX_CODES } from "@/lib/discount";
import { MAX_FLOWS } from "@/lib/flow-limits";
import { MOVE_BYTES, MOVE_KEY_BYTES, moveReads } from "@/lib/call-moves-read";

/** Database commands one further API request pays for. */
export const API_UNIT_COMMANDS = 20;
/** Bytes read from the database one further API request pays for. */
export const API_UNIT_BYTES = 1_000_000;
/** Bytes sent on to the caller one further API request pays for. */
export const API_UNIT_SENT_BYTES = 500_000;
/** Pages of a list at the creator's Stripe account, waited on, one further API request pays for. */
export const API_UNIT_STRIPE_PAGES = 3;
/** Trips to the database waited on one after another that one further API request pays for. */
export const API_UNIT_ROUND_TRIPS = 20;
/** Commands taking the further requests costs (lib/store-allowance.ts, takeAllowance): its count kept, and a store that pays nothing's place. */
export const MORE_TAKE_COMMANDS = 4;
/** And when they do not fit: the one command that gives them back (DECRBY). */
export const MORE_GIVE_BACK_COMMANDS = 1;
/** Trips to the database taking them waits on: a store that pays nothing's place, the count, and the giving back. */
export const MORE_TAKE_ROUND_TRIPS = 3;

/** What a reading does beyond the request's own key, store and answer. */
export type ReadWork = { commands: number; bytes: number; sent: number; stripePages: number; roundTrips: number };

const NONE: ReadWork = { commands: 0, bytes: 0, sent: 0, stripePages: 0, roundTrips: 0 };

const share = (w: ReadWork) =>
  w.commands / API_UNIT_COMMANDS + w.bytes / API_UNIT_BYTES + w.sent / API_UNIT_SENT_BYTES + w.stripePages / API_UNIT_STRIPE_PAGES + w.roundTrips / API_UNIT_ROUND_TRIPS;

/**
 * The further API requests a reading takes, beyond the request itself: none
 * when it does nothing more, else enough for its work and for taking them.
 * A size that is not a finite count of zero or more is never priced low:
 * it is refused by the caller before this (Infinity here).
 */
export function apiReadUnits(work: Partial<ReadWork>): number {
  const w = { ...NONE, ...work };
  if (Object.values(w).some((n) => !Number.isFinite(n) || n < 0)) return Number.POSITIVE_INFINITY;
  if (share(w) === 0) return 0;
  // Never rounded down: a share a hair over a whole number takes one more.
  return Math.ceil(share(withTaking(w)));
}

/** The work with what taking the further requests itself costs, at its most (refused, so given back). */
export function withTaking(w: ReadWork): ReadWork {
  return { ...w, commands: w.commands + MORE_TAKE_COMMANDS + MORE_GIVE_BACK_COMMANDS, roundTrips: w.roundTrips + MORE_TAKE_ROUND_TRIPS };
}

/** Two works done by one reading, taken together in one go (one take, so one taking's cost). */
export function addWork(a: Partial<ReadWork>, b: Partial<ReadWork>): ReadWork {
  const x = { ...NONE, ...a };
  const y = { ...NONE, ...b };
  return { commands: x.commands + y.commands, bytes: x.bytes + y.bytes, sent: x.sent + y.sent, stripePages: x.stripePages + y.stripePages, roundTrips: x.roundTrips + y.roundTrips };
}

/**
 * The further requests a reading that was set aside at its most and then
 * measured (lib/api-guard.ts, holdMoreApi) settles at: its measured work, and
 * one more when the measure passes what was set aside, for the second take
 * that then follows. A failure after the take (a database or Stripe error,
 * a crash) gives nothing back: what was set aside stays counted, by design,
 * because the work may have been done.
 */
export function settledUnits(work: Partial<ReadWork>, held: number): number {
  const units = apiReadUnits(work);
  return units > held ? units + 1 : units;
}

// ---------------------------------------------------------------- students

/** A student's row as a course keeps it: the hashed address it is filed under and the address, when they began and last came back. */
// A 254-character address in a three-byte script is 762 bytes, with its hashed key and its two times.
export const STUDENT_ROW_BYTES = 1_024;
/**
 * What a student marked done, read whole: a lesson id is 32 characters, with
 * room for each, for every lesson a course can hold and as many again for
 * lessons marked and later taken out of it (a review ceiling).
 */
// Known gap: the set is not pruned when a lesson is deleted, so a course whose lessons change a lot can pass
// this and its bytes are charged short; the real bound is the store's data room (lib/store-data.ts).
export const DONE_SET_BYTES = 2 * MAX_LESSONS * 40;
/** The course's blocked students are read in one command up to this many; past it, one per student on the page. */
export const BLOCKED_READ_MAX = 200;
/** A blocked student's hashed address, with room. */
export const BLOCKED_ENTRY_BYTES = 64;
/** One student as the API sends it. */
export const STUDENT_SENT_BYTES = 1_024;

/**
 * What reading the progress of one page of a course's students does, once the
 * page itself is read (lib/learn.ts, studentPage): each student's lessons
 * done, whether each is blocked, the rows and what is sent on.
 */
export function studentsPageWork(rows: number, blocked: number): ReadWork {
  if (rows <= 0) return { ...NONE };
  const whole = blocked <= BLOCKED_READ_MAX;
  return {
    commands: rows + (blocked <= 0 ? 0 : whole ? 1 : rows),
    bytes: rows * (STUDENT_ROW_BYTES + DONE_SET_BYTES) + (blocked <= 0 ? 0 : whole ? blocked * BLOCKED_ENTRY_BYTES : rows * 8),
    sent: rows * STUDENT_SENT_BYTES,
    stripePages: 0,
    roundTrips: 1,
  };
}

// ---------------------------------------------------------------- affiliates

/** How big the affiliate program is, counted before it is read (lib/affiliates.ts, bookSizes). */
export type BookSizes = {
  /** Whether readBook reads anything at all: a store with numbers, and a database. */
  kept: boolean;
  /** Entries in the seven records it reads whole: affiliates, clicks, sales, payouts, partners' shares, paid clicks, leads. */
  entries: number;
  /** Affiliates, each a row sent. */
  people: number;
  /** Leads, of which the open bookings' moves are read. */
  leads: number;
  /** PayPal refunds the store keeps, each read one after another. */
  paypalRefunds: number;
  /** Whether the creator's Stripe account is connected, so its invoices, refunds and disputes are read. */
  stripe: boolean;
  /** Products in the store, of which those sold as memberships through a link are read. */
  products: number;
};

/** The largest entry of any of the program's records: an affiliate's (an address, a note of MAX_NOTE_LENGTH in any script, the rest), with room. */
// Measured at 3,336 bytes for the largest writable affiliate (a 200-character note of control characters
// escaped six bytes each, and a PayPal address not checked by setPayAddress); room above it.
export const AFFILIATE_ENTRY_BYTES = 4_096;
/** One affiliate as the API sends it. */
export const AFFILIATE_SENT_BYTES = 512;
/** PayPal refunds readBook reads at the most (lib/paypal-sales.ts, readPayPalRefundsWithCoverage). */
export const BOOK_PAYPAL_REFUNDS = 500;
/** A PayPal sale's record, read for its refund: the order, the payment, the buyer, what the visit carried. */
export const PAYPAL_PAID_BYTES = 4_096;
/** Open bookings whose moves readBook reads at the most, a hundred at a command (lib/call-moves-read.ts). */
export const BOOK_MOVES = 200;
/** Invoices readBook reads at the most, so products named by them at the most (lib/affiliates.ts, INVOICE_PAGES of a hundred). */
export const BOOK_INVOICES = 1_000;
/** A product's listing, read for its title. */
export const LISTING_BYTES = 16_384;

/** What one reading of the affiliate program does (lib/affiliates.ts, readBook), counted from its sizes and the Stripe pages it may wait on. */
export function bookWork(s: BookSizes, stripePages: number): ReadWork {
  if (!s.kept) return { ...NONE };
  const any = s.entries > 0;
  const paypal = any ? Math.min(s.paypalRefunds, BOOK_PAYPAL_REFUNDS) : 0;
  const moves = Math.min(s.leads, BOOK_MOVES);
  const stripe = s.stripe && s.people > 0;
  const products = stripe ? Math.min(s.products, BOOK_INVOICES) : 0;
  return {
    // Counting it (seven counts and the PayPal refunds'), reading the seven records, then each read below; the moves a hundred at an MGET.
    commands: 8 + 7 + (any ? 1 + paypal : 0) + moveReads(moves) + products,
    bytes: s.entries * AFFILIATE_ENTRY_BYTES + paypal * PAYPAL_PAID_BYTES + moves * (MOVE_BYTES + MOVE_KEY_BYTES) + products * LISTING_BYTES,
    sent: s.people * AFFILIATE_SENT_BYTES,
    // Invoices while it has affiliates; refunds and disputes while it has anything credited.
    stripePages: s.stripe && any ? stripePages : 0,
    roundTrips: 2 + (any ? 1 + paypal : 0) + (moves ? 1 : 0) + (products ? 1 : 0),
  };
}

// ---------------------------------------------------------------- bookings

/** Pages of a hundred checkouts the bookings read at the most (lib/calls.ts, MAX_PAGES), so bookings at the most. */
export const BOOKING_PAGES = 5;
export const BOOKINGS_READ = BOOKING_PAGES * 100;
/** One booking as the API sends it: its buyer, its times and up to three answers to the creator's questions. */
export const BOOKING_SENT_BYTES = 2_048;

/**
 * What one reading of the bookings does (lib/calls.ts, paidCalls) at the
 * most: every page of checkouts, each booking's move read (a hundred keys at
 * an MGET, all in one trip: lib/call-records.ts, readMoves), and every
 * booking sent. How many there are is known only once Stripe has answered,
 * so it is taken whole, before; a store without Stripe connected reads nothing.
 */
export function bookingsWork(stripe: boolean): ReadWork {
  if (!stripe) return { ...NONE };
  return {
    commands: moveReads(BOOKINGS_READ),
    bytes: BOOKINGS_READ * (MOVE_BYTES + MOVE_KEY_BYTES),
    sent: BOOKINGS_READ * BOOKING_SENT_BYTES,
    stripePages: BOOKING_PAGES,
    roundTrips: 1,
  };
}

// ---------------------------------------------------------------- pages of products, the list and the members

/** How many rows one page of a long list holds (lib/api-read.ts, API_PAGE). */
export const API_PAGE_ROWS = 200;

/** One product as the API sends it: its title in any script, its link and the rest. */
export const PRODUCT_SENT_BYTES = 1_024;

/** What one page of products does: each listing the store's own record does not hold, read (lib/catalog-read-count.ts, listingsToRead), and every product sent. */
export function productsPageWork(listed: number, read: number): ReadWork {
  if (listed <= 0) return { ...NONE };
  return { commands: read, bytes: read * LISTING_BYTES, sent: listed * PRODUCT_SENT_BYTES, stripePages: 0, roundTrips: read ? 1 : 0 };
}

/**
 * What a page of a list read with HSCAN did, counted as it came back and
 * before it is sent: its commands, the bytes Redis answered with and the
 * bytes the answer holds. A page's rows cannot be counted before they are
 * read (COUNT is only a hint), so a page is set aside at its most first
 * (listPageMost), scanned, and settled at this, before anything is sent.
 */
export function scannedPageWork(commands: number, readBytes: number, sentBytes: number): ReadWork {
  return { commands, bytes: readBytes, sent: sentBytes, stripePages: 0, roundTrips: 1 };
}

/**
 * A contact of the list as kept, at its largest (lib/contacts.ts): its
 * address as the field (254 characters, three bytes each), and as the value
 * twenty product titles of MAX_TITLE_LENGTH (80) and their ids, a name of
 * MAX_CONTACT_NAME (100), MAX_CONTACT_TAGS (10) labels of MAX_TAG_LENGTH (40),
 * six times of up to 40 characters, the unsubscribe token and the keys, every
 * character escaped at six bytes. About 16,000 bytes; room above it.
 */
export const CONTACT_ROW_BYTES = 20_480;
/** A contact as the API sends it, at its largest: the same titles, ids, name and labels, its address escaped, five times. */
export const CONTACT_SENT_BYTES = 20_480;
/**
 * A community member as kept, at its largest (lib/community.ts, parseMember):
 * its key, an address, a display name and handle of MAX_DISPLAY_NAME (40),
 * MAX_QUESTIONS (3) answers of MAX_ANSWER (500) and questions of MAX_QUESTION
 * (200), the token and the keys, every character escaped at six bytes. About
 * 15,000 bytes; room above it.
 */
export const MEMBER_ROW_BYTES = 20_480;
/** A member as the API sends it: an address, a name and a handle escaped, two times and four flags. */
export const MEMBER_SENT_BYTES = 4_096;

/** A page of the list (one HSCAN) or of the members (an HSCAN and an HLEN) at its most, set aside before the scan: API_PAGE rows at their largest, read and sent. */
export function listPageMost(list: "leads" | "members", rows: number): ReadWork {
  return list === "leads"
    ? scannedPageWork(1, rows * CONTACT_ROW_BYTES, rows * CONTACT_SENT_BYTES)
    : scannedPageWork(2, rows * MEMBER_ROW_BYTES, rows * MEMBER_SENT_BYTES);
}

// ---------------------------------------------------------------- numbers

/** A day's count field: a source, tag, country or device name with its number. */
export const STATS_FIELD_BYTES = 128;
/** An all-time field, as Marktmorgen Path prices it (tests/plan-cost-registry.ts, PATH_READ). */
export const LIFE_FIELD_BYTES = 96;
/** Pages the numbers' sales read at the most (lib/stats.ts, readSales): checkouts and charges side by side, renewals, refunds, disputes. */
export const SALES_PAGES = 20;
export const RENEWAL_PAGES = 10;
export const REFUND_READ_PAGES = 5;
export const DISPUTE_READ_PAGES = 3;
export const NUMBERS_STRIPE_PAGES = 2 * SALES_PAGES + RENEWAL_PAGES + REFUND_READ_PAGES + DISPUTE_READ_PAGES;
/** PayPal sales the numbers read at the most (readPaidSales, a hundred a page), and PayPal refunds (readPayPalRefundsWithCoverage). */
export const NUMBERS_PAYPAL_SALES = SALES_PAGES * 100;
/** The numbers as sent, with every row (?details=all): a review ceiling. */
export const NUMBERS_SENT_BYTES = 1_000_000;

/** What the numbers read can be sized by first. */
export type NumbersSizes = {
  /** Whether the store keeps numbers at all (an id for them, and a database). */
  kept: boolean;
  /** Whether it reads sales (lib/stats.ts, readsSales). */
  sales: boolean;
  stripe: boolean;
  /** PayPal sales and refunds it keeps, of which it reads up to its most. */
  paypalSales: number;
  paypalRefunds: number;
};

/**
 * What one reading of the numbers does (lib/stats-report.ts readNumbers,
 * lib/mcp-tools.ts readFullNumbers): ninety days of counts and the ninety
 * before, the all-time record (read, its gap kept, trimmed), and with sales
 * the PayPal sales and refunds counted first and every Stripe page at its
 * most. The all-time record's one filling from the days before it (once in a
 * store's life, under a lock) is not a reading's: it is not priced here.
 * The listings readFullNumbers names are taken apart, once counted.
 */
export function numbersWork(s: NumbersSizes): ReadWork {
  if (!s.kept) return { ...NONE };
  const paypalSales = s.sales ? Math.min(s.paypalSales, NUMBERS_PAYPAL_SALES) : 0;
  const paypalRefunds = s.sales ? Math.min(s.paypalRefunds, BOOK_PAYPAL_REFUNDS) : 0;
  return {
    commands: 3 * STATS_DAYS + 6 + 4 + (s.sales ? 2 + 1 + paypalRefunds : 0),
    bytes: STATS_DAYS * DAY_FIELDS_MAX * STATS_FIELD_BYTES + STATS_DAYS * 64 + LIFE_WRITE_MAX * LIFE_FIELD_BYTES + (paypalSales + paypalRefunds) * PAYPAL_PAID_BYTES,
    sent: NUMBERS_SENT_BYTES,
    stripePages: s.sales && s.stripe ? NUMBERS_STRIPE_PAGES : 0,
    roundTrips: 4 + (s.sales ? 2 + 1 + paypalRefunds : 0),
  };
}

/** How long the API and the MCP tools keep a copy of the numbers they read (lib/api-numbers.ts): an hour, said as `asOf`. */
export const NUMBERS_KEPT_SECONDS = 60 * 60;
/** The largest copy of the numbers kept: a larger reading is not kept, so every reading of it is read whole and taken as such. */
export const NUMBERS_KEPT_BYTES = 1_000_000;

/** What keeping a copy of the numbers adds to a reading of them: its size looked up first, and the copy written (at its largest). */
export const NUMBERS_KEEP_WORK: ReadWork = { commands: 2, bytes: NUMBERS_KEPT_BYTES, sent: 0, stripePages: 0, roundTrips: 2 };

/** A reading of the numbers from their kept copy: its size looked up, the copy read (`bytes`, measured first) and the answer sent. */
export function keptNumbersWork(bytes: number, sent: number): ReadWork {
  return { commands: 2, bytes, sent, stripePages: 0, roundTrips: 2 };
}

/** The listings readFullNumbers reads for the products the numbers name, once it knows them. */
export function listingsWork(read: number): ReadWork {
  return read > 0 ? { commands: read, bytes: read * LISTING_BYTES, sent: 0, stripePages: 0, roundTrips: 1 } : { ...NONE };
}

// ---------------------------------------------------------------- memberships

/** Pages of subscriptions and of invoices the membership numbers read when not kept (lib/membership-numbers.ts, MAX_PAGES each). */
export const MEMBERSHIP_PAGES = 2 * 20;
/** The membership numbers as kept and as sent: by product, by channel, why members left, thirteen months: a review ceiling. */
export const MEMBERSHIP_NUMBERS_BYTES = 256_000;
/**
 * What get_memberships does before Stripe and before naming them: whether
 * the numbers are kept and how big they are looked up (`keptBytes`,
 * measured), the kept numbers read and the answer sent. The products they
 * name are read afterwards, counted first (listingsWork), or named by their
 * id when that is not left.
 */
export function membershipsWork(keptBytes = MEMBERSHIP_NUMBERS_BYTES): ReadWork {
  return { commands: 2, bytes: keptBytes, sent: MEMBERSHIP_NUMBERS_BYTES, stripePages: 0, roundTrips: 2 };
}
/**
 * And when they are not kept: every page of subscriptions and invoices, and the numbers kept again; with what members
 * wrote looked up among the store's deleted people (one HMGET) and kept by a script that looks them up again where it
 * writes (2 more beside its SET), for up to 70 comments and three addresses each (lib/membership-numbers.ts,
 * SHOWN_COMMENTS, COMMENT_ADDRESSES; Codex E2 on #2111).
 */
export const MEMBERSHIPS_COLD_WORK: ReadWork = { commands: 1 + 1 + 2, bytes: MEMBERSHIP_NUMBERS_BYTES + 2 * 70 * 3 * (64 + 64), sent: 0, stripePages: MEMBERSHIP_PAGES, roundTrips: 1 + 1 };

// ---------------------------------------------------------------- emails

/** Broadcasts get_emails reads (lib/mcp-tools.ts, emailsTool), and what one sent is told back: its subject and numbers. */
export const EMAILS_BROADCASTS = 30;
export const EMAIL_SENT_BYTES = 1_024;
/** A sequence's counts, as the store's data registry prices them (20 KB a sequence). */
export const FLOW_STATS_BYTES = 20 * 1024;
/** Pages of sales what the emails sold reads when not kept (lib/mail-revenue.ts, PAGES): checkouts and charges side by side. */
export const MAIL_REVENUE_PAGES = 2 * 10;
/**
 * What the emails sold, as kept (by campaign), counted when it is not kept yet
 * and is about to be made. Not a ceiling: a kept copy is measured (STRLEN)
 * before it is read and every reading is settled at the bytes it read or kept
 * (lib/mcp-tools.ts, emailsTool).
 */
export const MAIL_REVENUE_BYTES = 64_000;

/**
 * What get_emails reads, sized first: its broadcasts and its sequences
 * measured by their bytes (one LRANGE and a STRLEN each), then the list's
 * counts, the records, each sequence's counts at the most and what they sold
 * at the size it is kept at (`revenueBytes`, measured: 0 when it is not kept),
 * and every one told back.
 */
export function emailsWork(s: { broadcasts: number; broadcastBytes: number; flowBytes: number; revenueBytes: number }): ReadWork {
  return {
    commands: 2 + s.broadcasts + 3 + 1 + 1 + s.broadcasts + MAX_FLOWS + 1,
    bytes: s.broadcastBytes + s.flowBytes + MAX_FLOWS * FLOW_STATS_BYTES + s.revenueBytes,
    sent: (s.broadcasts + MAX_FLOWS) * EMAIL_SENT_BYTES,
    stripePages: 0,
    roundTrips: 2 + 4,
  };
}
/** What get_emails looks up before it sets aside: whether what they sold is kept and how big (STRLEN), and the PayPal sales and refunds it would read (two ZCARD), side by side. */
export const EMAILS_PROBE_WORK: ReadWork = { commands: 3, bytes: 0, sent: 0, stripePages: 0, roundTrips: 1 };
/**
 * And when what they sold is not kept: every page of sales, the PayPal sales
 * counted first, kept again. The copy kept is known only once it is made, so
 * it is set aside at MAIL_REVENUE_BYTES and settled at its size (`keptBytes`).
 */
export function mailRevenueColdWork(paypalSales: number, keptBytes = MAIL_REVENUE_BYTES): ReadWork {
  const paypal = Math.min(paypalSales, 10 * 100);
  return { commands: 3, bytes: paypal * PAYPAL_PAID_BYTES + keptBytes, sent: 0, stripePages: MAIL_REVENUE_PAGES, roundTrips: 2 };
}

// ---------------------------------------------------------------- what buyers bought next

/** A step of what buyers bought next as get_product_numbers sends it: two titles escaped at six bytes, the numbers and the indentation. */
export const NEXT_STEP_SENT_BYTES = 1_200;
/** The least bytes one step takes as kept (lib/next-bought.ts): {"id":"…","buyers":3,"days":0}. */
export const NEXT_STEP_KEPT_MIN_BYTES = 28;

/**
 * What get_product_numbers reads beside the numbers: what buyers bought next
 * (its size `pathBytes` looked up first) and what it sends of it, at most a
 * step for every NEXT_STEP_KEPT_MIN_BYTES kept. Set aside at its most and
 * settled at what was sent (lib/api-guard.ts, holdMoreApi). The products it
 * names that the numbers do not are read apart, counted first (listingsWork).
 */
export function boughtNextWork(pathBytes: number, sent = (Math.ceil(pathBytes / NEXT_STEP_KEPT_MIN_BYTES) + 5) * NEXT_STEP_SENT_BYTES): ReadWork {
  return { commands: 2, bytes: pathBytes, sent, stripePages: 0, roundTrips: 2 };
}

// ---------------------------------------------------------------- events and codes

/** An entry of a store's delivery log (a delivery's id), with room. */
export const LOG_ENTRY_BYTES = 64;

/**
 * The size of a reading of the recent events (lib/api-read.ts, recentEvents):
 * the deliveries in the store's log, the bytes read (the log and each
 * delivery as kept) and the bytes sent.
 */
export type EventsSize = { deliveries: number; bytes: number; sent: number };

/**
 * The most a reading of the recent events can be: LOG_SIZE deliveries, each
 * kept at DELIVERY_MAX_BYTES at most (bounded where it is made,
 * lib/webhooks.ts, emitEvent), and RECENT_MESSAGES_MAX of them sent.
 */
export const EVENTS_MOST: EventsSize = {
  deliveries: LOG_SIZE,
  bytes: LOG_SIZE * (LOG_ENTRY_BYTES + DELIVERY_MAX_BYTES),
  sent: RECENT_MESSAGES_MAX * (DELIVERY_MAX_BYTES + 1),
};

/**
 * What the recent events do: the store's log read (LRANGE), each delivery in
 * it measured (STRLEN), then all read in one script (lib/webhooks.ts,
 * READ_DELIVERIES: each measured again and read, READ_DELIVERIES_CALLS_EACH)
 * and the messages of the type asked for sent. Without an argument, its most.
 */
export function eventsWork(s: EventsSize = EVENTS_MOST): ReadWork {
  return { commands: s.deliveries > 0 ? 2 + (1 + READ_DELIVERIES_CALLS_EACH) * s.deliveries : 1, bytes: s.bytes, sent: s.sent, stripePages: 0, roundTrips: s.deliveries > 0 ? 3 : 1 };
}

/**
 * The measuring alone at its most, set aside before the log is read (Codex
 * G2, #2192: fifty sizes were looked up before any request beyond the first
 * was taken): the log and a size for each delivery it can hold. Part of
 * eventsWork, which the whole reading is settled at (lib/api-read.ts,
 * recentEvents).
 */
export const EVENTS_PROBE_MOST: ReadWork = { commands: 1 + LOG_SIZE, bytes: LOG_SIZE * LOG_ENTRY_BYTES, sent: 0, stripePages: 0, roundTrips: 2 };

/**
 * The most a reading of the recent events can send, from the sizes looked up
 * first: the `most` largest deliveries, since a message is never longer than
 * the delivery it is kept in (escaped once more there), with a comma each.
 */
export function eventsSentMost(sizes: readonly number[], most: number): number {
  return [...sizes].sort((a, b) => b - a).slice(0, Math.max(0, most)).reduce((n, size) => n + size + 1, 0);
}

/** A discount code as sent; the codes are one page of the creator's Stripe account (lib/discount.ts, MAX_CODES a page). */
export const CODE_SENT_BYTES = 1_024;
export function codesWork(): ReadWork {
  return { commands: 0, bytes: 0, sent: MAX_CODES * CODE_SENT_BYTES, stripePages: 1, roundTrips: 0 };
}
/** Making a code (POST /api/v1/codes): two calls to the creator's Stripe account (the coupon, then its code), and the code sent. */
export function codeMakeWork(): ReadWork {
  return { commands: 0, bytes: 0, sent: CODE_SENT_BYTES, stripePages: 2, roundTrips: 0 };
}
/** Switching a code off (DELETE /api/v1/codes): the codes read to find it, the call that switches it off and the codes read again and sent, at their most. */
export function codeStopWork(): ReadWork {
  return { commands: 0, bytes: 0, sent: MAX_CODES * CODE_SENT_BYTES, stripePages: 3, roundTrips: 0 };
}

// ---------------------------------------------------------------- the store's pages and courses (MCP read tools, 631 [AA1] (a))

/** A product's long description, read whole: its longest, three bytes a UTF-16 unit at most (lib/product-about.ts). */
export const ABOUT_BYTES = MAX_ABOUT_LENGTH * 3;
/** A sales page as stored, read whole (lib/sales-page.ts). */
export const PAGE_BYTES = MAX_STORED_PAGE_BYTES;
/** A version of a sales page as kept: the page and its time (lib/sales-page-store.ts, "<at>\n<page>"). */
export const PAGE_VERSION_BYTES = MAX_STORED_PAGE_BYTES + 32;
/** A course's record, read whole: the same ceiling the community walk reads it at (lib/community-walk.ts WALK_COURSE_BYTES). */
export const COURSE_BYTES = 512_000;
/** A lesson's text in any script (lib/course.ts MAX_BODY_LENGTH). */
export const BODY_BYTES = MAX_BODY_LENGTH * 3;
/** A lesson's quiz, every question, choice and explanation at its longest in any script, with room for its fields. */
export const QUIZ_BYTES = MAX_QUESTIONS * (MAX_QUESTION_LENGTH + MAX_CHOICES * MAX_CHOICE_LENGTH + MAX_EXPLANATION_LENGTH) * 3 + 16_384;
/** A lesson's task: its prompt at its longest in any script, with room for its setup (lib/assignment-rules.ts). */
export const TASK_BYTES = MAX_TASK_PROMPT * 3 + 4_096;
/** A page test's counts (views, checkouts, sales and money of each version), with room. */
export const TEST_COUNTS_BYTES = 1_024;
/** What a page test's answer sends besides its counts: the tested headline and line, with room. */
export const TEST_SENT_BYTES = 8_192;
/** What a reading of a page's depth sends: each block's share and the depth record's figures, with room. */
export const READING_SENT_BYTES = MAX_BLOCKS * 256 + DEPTH_RECORD_BYTES;
/** Saved sections a store's library holds at the most, on any plan (lib/funnel-share-rules.ts, savedBlocks; the write refuses past it). */
export const SAVED_SECTIONS_MAX = Math.max(...Object.values(SHARE_LIMITS).map((limits) => limits.savedBlocks));
/**
 * One saved section as stored and as sent (lib/saved-blocks.ts): the write
 * measures its blocks in characters (MAX_SECTION_BYTES), and a character is at
 * most three bytes of UTF-8 for each unit JavaScript counts; with its name
 * (MAX_SECTION_NAME) and its id and time.
 */
export const SECTION_BYTES = (MAX_SECTION_BYTES + MAX_SECTION_NAME + 256) * 3;
/** What an answer's own fields send besides what it read: names, ids, notes. */
export const TOOL_NOTE_BYTES = 2_048;

/** get_product_description: the listing (listingsWork) and then the description. */
export function productTextWork(): ReadWork {
  return { commands: 1, bytes: ABOUT_BYTES, sent: ABOUT_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 1 };
}

/** get_sales_page: the listing and then the page, sent block by block. */
export function salesPageWork(): ReadWork {
  return { commands: 1, bytes: PAGE_BYTES, sent: PAGE_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 1 };
}

/** get_course_outline: the listing and then the course's record, its outline sent. */
export function courseOutlineWork(): ReadWork {
  return { commands: 1, bytes: COURSE_BYTES, sent: COURSE_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 1 };
}

/** get_lesson: the listing, the course's record, then the lesson's text, quiz and task in one go. */
export function lessonWork(): ReadWork {
  return { commands: 4, bytes: COURSE_BYTES + BODY_BYTES + QUIZ_BYTES + TASK_BYTES, sent: BODY_BYTES + QUIZ_BYTES + TASK_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 2 };
}

/** get_page_test: the listing, the page, then the test's counts. */
export function pageTestWork(): ReadWork {
  return { commands: 2, bytes: PAGE_BYTES + TEST_COUNTS_BYTES, sent: TEST_SENT_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 2 };
}

/** get_page_reading: the listing, then the page and its depth record in one go. */
export function pageReadingWork(): ReadWork {
  return { commands: 2, bytes: PAGE_BYTES + DEPTH_RECORD_BYTES, sent: READING_SENT_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 1 };
}

/** get_page_versions: the listing, how many versions are kept (LLEN), then those versions; one sent whole, or the list. */
/** What a count command (LLEN, HLEN) answers: one integer, never more than this. */
export const COUNT_REPLY_BYTES = 32;

export function pageVersionsWork(versions: number, one: boolean): ReadWork {
  const n = Math.min(Math.max(versions, 0), MAX_VERSIONS);
  return { commands: 2, bytes: COUNT_REPLY_BYTES + n * PAGE_VERSION_BYTES, sent: (one ? PAGE_BYTES : n * 256) + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 2 };
}

/** list_saved_blocks: how many sections the library holds (HLEN), then those sections, read and sent. */
export function savedBlocksWork(sections: number): ReadWork {
  const n = Math.min(Math.max(sections, 0), SAVED_SECTIONS_MAX);
  return { commands: 2, bytes: COUNT_REPLY_BYTES + n * SECTION_BYTES, sent: n * SECTION_BYTES + TOOL_NOTE_BYTES, stripePages: 0, roundTrips: 2 };
}

/** What a proposal adds to the agent's book beyond its "before" and "after": its id, kind, target, who asked and when. */
export const PROPOSAL_ENTRY_BYTES = 1_024;

/**
 * propose_product_description (631 [AA1] (c)): the product's current
 * description read, the store's lock on its book of proposals taken, the book
 * measured under it (STRLEN, where no other change can make it grow), read,
 * and written back whole with the new proposal in it, the lock let go, and
 * the data room around it. The listing, read three times (to find the
 * product, to check its words and with its description), is counted apart
 * (listingsWork). `bookBytes` 0 is what is taken before the book is measured.
 */
export function proposeWork(bookBytes: number, kindMaxBytes: number): ReadWork {
  const book = Math.max(bookBytes, 0);
  return {
    commands: 10,
    bytes: COUNT_REPLY_BYTES + ABOUT_BYTES + book,
    sent: book + kindMaxBytes + PROPOSAL_ENTRY_BYTES + TOOL_NOTE_BYTES,
    stripePages: 0,
    roundTrips: 8,
  };
}

// ---------------------------------------------------------------- bundle choices and imports (MCP read tools, 631 [AA1] (a))

/** A product's cached card (its title, price and whether it has a page), as kept for searching: a review ceiling, settled at what was read. */
export const CARD_READ_BYTES = 1_024;
/** Names list_bundle_choices looks through for a search in one call (lib/bundle-choices.ts, SEARCH_STRETCH, one HMGET). */
export const BUNDLE_SEARCH_STRETCH = 100;
/** Listings one page of list_bundle_choices reads at the most (lib/bundle-choices.ts, PICKER_PAGE). */
export const BUNDLE_PAGE_LISTINGS = 20;

/**
 * list_bundle_choices (lib/bundle-choices.ts, bundleChoicesPage): with a
 * search, the cached cards of a stretch of products in one HMGET; then the
 * listings of the page, in one go; and the page sent, a product each and the
 * note. Set aside at its most (BUNDLE_CHOICES_MOST) before anything is read
 * and settled at this for what was read, or at what was really read and sent
 * where that came to more (lib/mcp-tools.ts, bundleChoicesTool).
 */
export function bundleChoicesWork(cards: number, listings: number): ReadWork {
  const c = Math.max(cards, 0);
  const l = Math.max(listings, 0);
  return {
    commands: (c > 0 ? 1 : 0) + l,
    bytes: c * CARD_READ_BYTES + l * LISTING_BYTES,
    sent: l * PRODUCT_SENT_BYTES + 2 * TOOL_NOTE_BYTES,
    stripePages: 0,
    roundTrips: (c > 0 ? 1 : 0) + (l > 0 ? 1 : 0),
  };
}
/** list_bundle_choices at its most: a whole stretch of cards and a whole page of listings (Codex G2 on #1933: twenty listings read on the door's one request). */
export const BUNDLE_CHOICES_MOST: ReadWork = bundleChoicesWork(BUNDLE_SEARCH_STRETCH, BUNDLE_PAGE_LISTINGS);

/** Imports a store's history keeps, all of which get_imports reads (lib/imports.ts, IMPORTS_LIST_SIZE). */
export const IMPORTS_READ = 10;
/** An entry of the imports' index: an import's id (24 hexadecimal characters, lib/imports.ts IMPORT_ID_PATTERN), with room. */
export const IMPORT_ID_BYTES = 64;
/** An import's record (lib/imports.ts), read whole: its counts, kind, source, file name, tags and where it is: a review ceiling, settled at what was read. */
export const IMPORT_JOB_BYTES = 16_384;
/** An import as get_imports sends it: counts only. */
export const IMPORT_SENT_BYTES = 1_024;

/**
 * get_imports (lib/imports.ts, storeImportsRead): the index (one LRANGE),
 * then each import it names (a GET each, in one go), each sent as counts.
 * Set aside at its most (IMPORTS_MOST) before the index is read and settled
 * at this for the imports it named, or at what was really read and sent
 * where that came to more (lib/mcp-tools.ts, importsTool).
 */
export function importsWork(imports: number): ReadWork {
  const n = Math.max(imports, 0);
  return {
    commands: 1 + n,
    bytes: n * (IMPORT_ID_BYTES + IMPORT_JOB_BYTES),
    sent: n * IMPORT_SENT_BYTES + TOOL_NOTE_BYTES,
    stripePages: 0,
    roundTrips: n > 0 ? 2 : 1,
  };
}
/** get_imports at its most: every import the history keeps. */
export const IMPORTS_MOST: ReadWork = importsWork(IMPORTS_READ);

app/api/mcp/route.ts.content:
import { apiAgent, apiStore, holdMoreApi, takeMoreApi } from "@/lib/api-guard";
import { proposeDescription } from "@/lib/agent-propose";
import { BookReadRefused } from "@/lib/agent-book";
import { PRODUCT_DESCRIPTION } from "@/lib/agent-kinds";
import { addWork, apiReadUnits, listingsWork, proposeWork } from "@/lib/api-read-rules";
import { listingsToRead } from "@/lib/catalog-read-count";
import { limited } from "@/lib/request-guard";
import { products, storeInfo } from "@/lib/api-read";
import { apiNumbers } from "@/lib/api-numbers";
import { summaryOf } from "@/lib/stats-report";
import type { StatsData } from "@/lib/stats";
import {
  affiliatesTool,
  bundleChoicesTool,
  buyersTool,
  channelsTool,
  emailsTool,
  funnelTool,
  importsTool,
  insightsTool,
  membershipsTool,
  productTextTool,
  productsTool,
  readCourseTool,
  readLessonTool,
  readPageReadingTool,
  readPageTestTool,
  readPageVersionsTool,
  readSalesPageTool,
  savedBlocksTool,
  windowOf,
} from "@/lib/mcp-tools";

/**
 * The Marktmorgen MCP server (added 11 October 2026): a creator's AI
 * assistant — Claude, ChatGPT, Cursor, anything that speaks the Model Context
 * Protocol — can ask about their store in plain words: "which channel made me
 * money this month?", "what did my October reel bring?".
 *
 * Streamable HTTP, JSON only, one JSON-RPC message per request; a GET is
 * answered 405, because no stream is offered. The key is the same API key as
 * /api/v1, through the same door (lib/api-guard.ts) and the same limit per
 * minute; `initialize` alone is answered before the key is read, so a client
 * can learn what this is before it has been given anything, and that answer
 * carries no store's data.
 *
 * Read only: numbers, products, memberships, emails and affiliates, each as
 * the studio shows them (lib/mcp-tools.ts, added 12 October 2026, beside the
 * first three). Buyers', members', subscribers' and affiliates' addresses
 * and words stay out of it on purpose: an assistant's conversation is kept by
 * whoever runs the assistant, and the people on a creator's list never agreed
 * to be read there. The API is where a creator's own tools read those.
 */
import { MCP_INSTRUCTIONS, MCP_PROTOCOL as PROTOCOL, MCP_SERVER, MCP_TOOLS as TOOLS } from "@/lib/mcp-catalog";

type Rpc = { jsonrpc?: unknown; id?: unknown; method?: unknown; params?: unknown };

const json = (body: unknown, status = 200) =>
  Response.json(body, { status, headers: { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" } });
const result = (id: unknown, value: unknown) => json({ jsonrpc: "2.0", id, result: value });
const failure = (id: unknown, code: number, message: string) => json({ jsonrpc: "2.0", id: id ?? null, error: { code, message } });
const said = (value: unknown, isError = false) => ({ content: [{ type: "text", text: JSON.stringify(value, null, 2) }], isError });

export async function GET() {
  return new Response("This MCP server answers POST only.", { status: 405, headers: { Allow: "POST" } });
}

/** The most one JSON-RPC message may weigh: far past any call a tool takes. */
const MAX_RPC_BYTES = 16_000;

export async function POST(request: Request) {
  let message: Rpc;
  try {
    // Read only as far as MAX_RPC_BYTES, whether or not a length was declared (docs/security-audit-2026-10-18.md, MM-SA-10).
    message = (await (await limited(request, MAX_RPC_BYTES)).json()) as Rpc;
  } catch {
    return failure(null, -32700, "Parse error");
  }
  if (Array.isArray(message)) return failure(null, -32600, "One message per request.");
  if (!message || message.jsonrpc !== "2.0" || typeof message.method !== "string") return failure(message?.id, -32600, "Invalid request");
  const { id, method } = message;
  // A notification has no id and wants no answer.
  if (id === undefined || id === null) return new Response(null, { status: 202 });

  if (method === "initialize") {
    return result(id, {
      protocolVersion: PROTOCOL,
      capabilities: { tools: {} },
      serverInfo: MCP_SERVER,
      instructions: MCP_INSTRUCTIONS,
    });
  }
  if (method === "ping") return result(id, {});

  // A tool that prepares a change needs a key that may (631 [AA1] (c)); checked instead of the plain read, so the call is counted once.
  const asked = (message.params ?? {}) as { name?: unknown; arguments?: Record<string, unknown> };
  if (method === "tools/call" && asked.name === "propose_product_description") {
    const agent = await apiAgent(request, "draft");
    if (agent instanceof Response) {
      const refusal = (await agent.json().catch(() => null)) as { message?: unknown } | null;
      return failure(id, -32001, typeof refusal?.message === "string" ? refusal.message : "This key cannot prepare changes for you to confirm.");
    }
    // Paid for before it reads (lib/api-read-rules.ts, proposeWork): first all but the book; then the book, measured
    // under its lock where it cannot grow, at what it weighs, before it is read. Refused, the refusal's own sentence.
    const named = typeof asked.arguments?.product === "string" ? asked.arguments.product.slice(0, 40) : "";
    const envelope = (book: number) => apiReadUnits(addWork(listingsWork(3 * listingsToRead(agent.store, named ? [named] : [])), proposeWork(book, PRODUCT_DESCRIPTION.maxBytes)));
    const refusedWords = async (refusal: Response) => {
      const words = (await refusal.json().catch(() => null)) as { message?: unknown } | null;
      return failure(id, -32001, typeof words?.message === "string" ? words.message : "That could not be prepared just now. Try again in a moment.");
    };
    const first = envelope(0);
    const opened = await takeMoreApi(agent.store, first);
    if (opened) return refusedWords(opened);
    let refusal: Response | null = null;
    const admit = async (bytes: number) => {
      refusal = await takeMoreApi(agent.store, envelope(bytes) - first, first);
      return refusal === null;
    };
    try {
      return result(id, await proposeDescription(agent.store, agent.keyId, asked.arguments ?? {}, admit));
    } catch (error) {
      if (error instanceof BookReadRefused && refusal) return refusedWords(refusal);
      if (error instanceof BookReadRefused) return failure(id, -32001, "That could not be prepared just now. Try again in a moment.");
      throw error;
    }
  }

  const store = await apiStore(request);
  if (store instanceof Response) {
    // The refusal's own sentence (a pause, the month used, the minute), so an
    // assistant never asks for a key that was already accepted (232 [CA1] 4b4c).
    if (store.status === 401) return failure(id, -32001, "Send your Marktmorgen API key as: Authorization: Bearer nl_live_…");
    const said = (await store.json().catch(() => null)) as { message?: unknown } | null;
    return failure(id, -32001, typeof said?.message === "string" ? said.message : "That could not be read just now. Try again in a moment.");
  }

  if (method === "tools/list") return result(id, { tools: TOOLS });
  if (method !== "tools/call") return failure(id, -32601, "Method not found");

  const params = (message.params ?? {}) as { name?: unknown; arguments?: Record<string, unknown> };
  try {
    if (params.name === "get_store") return result(id, said(storeInfo(store)));
    // Every other tool takes what it reads past the door before reading it (lib/api-read-rules.ts);
    // refused, the refusal's own sentence, as the door's.
    const charge = (more: number, taken?: number) => takeMoreApi(store, more, taken);
    const hold = (most: number) => holdMoreApi(store, most);
    const refusedWith = async (refusal: Response) => {
      const words = (await refusal.json().catch(() => null)) as { message?: unknown } | null;
      return failure(id, -32001, typeof words?.message === "string" ? words.message : "That could not be read just now. Try again in a moment.");
    };
    const answer = async (read: unknown) => (read instanceof Response ? refusedWith(read) : result(id, said(read)));
    const days = windowOf(params.arguments?.days);
    const windowed: Record<string, (data: StatsData) => unknown | Promise<unknown>> = {
      get_numbers: (data) => summaryOf(data),
      get_revenue_by_channel: (data) => channelsTool(data, days),
      get_funnel: (data) => funnelTool(data, days),
      get_product_numbers: (data) => productsTool(store, data, days, { hold, charge }),
      get_buyers: (data) => buyersTool(data, days),
      get_worth_knowing: (data) => insightsTool(data, days),
    };
    const tool = typeof params.name === "string" && Object.hasOwn(windowed, params.name) ? windowed[params.name] : undefined;
    if (typeof tool === "function") {
      // The numbers, from the copy kept an hour or read anew, paid for first (lib/api-numbers.ts); get_numbers without the products' listings, as /api/v1/stats.
      const read = await apiNumbers(store, params.name === "get_numbers" ? "plain" : "full", charge, hold);
      if (read instanceof Response) return refusedWith(read);
      if (!read) return result(id, said({ error: "Your numbers could not be read just now. Try again in a moment." }, true));
      const value = {
        ...((await tool(read.data)) as Record<string, unknown>),
        asOf: read.asOf,
        ...(read.listed ? {} : { products_note: "The products' names were not read: your store's API requests left did not cover them, or they could not be read just now. An empty products list here is not a store without products." }),
      };
      const answer = said(value);
      // What the answer sends is settled before it is sent.
      const refused = await read.settle(Buffer.byteLength(answer.content[0].text));
      return refused ? refusedWith(refused) : result(id, answer);
    }
    if (params.name === "get_memberships") return answer(await membershipsTool(store, charge));
    if (params.name === "get_emails") return answer(await emailsTool(store, { charge, hold }));
    if (params.name === "get_affiliates") return answer(await affiliatesTool(store, charge));
    // The store's pages and courses (631 [AA1] (a)): each takes what it reads, at its most, before reading (lib/api-read-rules.ts).
    const unknownProduct = { error: "There is no product with that id in this store. Use list_products for the ids." };
    const productArg = typeof params.arguments?.product === "string" ? params.arguments.product.slice(0, 40) : "";
    if (params.name === "get_product_description" || params.name === "get_sales_page") {
      if (!productArg) return result(id, said(unknownProduct, true));
      const found = await (params.name === "get_sales_page" ? readSalesPageTool(store, productArg, charge) : productTextTool(store, productArg, charge));
      if (found instanceof Response) return refusedWith(found);
      return result(id, found ? said(found, "error" in found) : said(unknownProduct, true));
    }
    if (params.name === "get_course_outline" || params.name === "get_lesson") {
      const lesson = typeof params.arguments?.lesson === "string" ? params.arguments.lesson.slice(0, 40) : "";
      const missing = { error: params.name === "get_lesson" ? "There is no such lesson in this store's courses. Use get_course_outline for the ids." : "There is no course with that id in this store. Use list_products for the ids." };
      if (!productArg || (params.name === "get_lesson" && !lesson)) return result(id, said(missing, true));
      const found = params.name === "get_lesson" ? await readLessonTool(store, productArg, lesson, charge) : await readCourseTool(store, productArg, charge);
      if (found instanceof Response) return refusedWith(found);
      return result(id, found ? said(found) : said(missing, true));
    }
    if (params.name === "get_page_test") {
      if (!productArg) return result(id, said(unknownProduct, true));
      const tested = await readPageTestTool(store, productArg, charge);
      if (tested instanceof Response) return refusedWith(tested);
      return result(id, tested.found ? said(tested.value) : said({ error: tested.error }, true));
    }
    if (params.name === "get_page_reading") {
      if (!productArg) return result(id, said(unknownProduct, true));
      const reading = await readPageReadingTool(store, productArg, charge);
      if (reading instanceof Response) return refusedWith(reading);
      return result(id, reading ? said(reading, "error" in reading) : said(unknownProduct, true));
    }
    if (params.name === "get_page_versions") {
      const raw = params.arguments?.version;
      const version = raw === undefined || raw === null ? null : Number.isInteger(raw) && (raw as number) >= 0 && (raw as number) < 100 ? (raw as number) : -1;
      if (version === -1) return result(id, said({ error: "version is a whole number from the list, 0 for the newest." }, true));
      if (!productArg) return result(id, said(unknownProduct, true));
      const found = await readPageVersionsTool(store, productArg, version, hold);
      if (found instanceof Response) return refusedWith(found);
      return result(id, found.found ? said(found.value) : said({ error: found.error }, true));
    }
    if (params.name === "list_saved_blocks") {
      const listed = await savedBlocksTool(store, hold);
      if (listed instanceof Response) return refusedWith(listed);
      return result(id, said(listed, listed.sections === null));
    }
    // What a bundle can be made of, and the store's imports (631 [AA1] (a)): each sets aside its most before reading
    // and is settled at what it read and sends before it is sent (lib/mcp-tools.ts).
    if (params.name === "list_bundle_choices" || params.name === "get_imports") {
      const read = params.name === "get_imports" ? await importsTool(store, hold) : await bundleChoicesTool(store, params.arguments ?? {}, hold);
      if (read instanceof Response) return refusedWith(read);
      return result(id, read.found ? said(read.value) : said({ error: read.error }, true));
    }
    if (params.name === "list_products") {
      const cursor = typeof params.arguments?.cursor === "string" ? params.arguments.cursor.slice(0, 200) : null;
      return answer(await products(store, cursor, charge));
    }
    return result(id, said({ error: `There is no tool called ${String(params.name).slice(0, 40)}.` }, true));
  } catch (error) {
    console.error("mcp: a tool failed", error);
    return result(id, said({ error: "That could not be read just now. Try again in a moment." }, true));
  }
}

lib/bundle-rules.ts.content:
/**
 * The rules of a bundle: one product that hands over several of the store's
 * own products at a price of its own.
 *
 * A bundle holds no file, link or lessons of its own. It holds a list of the
 * store's products — two to twenty — and a buyer who pays for it gets every
 * one of them exactly as if each had been bought on its own: its download or
 * its link, its course, its licence key, its stamped PDF, its place on the
 * buyer's list of purchases, the right to review it.
 *
 * What may go in one is what can be handed over whole, once, for good: a
 * one-off paid product with a file, a link or a course with lessons. Not a
 * membership (it ends), not a call (it is a time, booked), not a product with
 * several prices (which one?), not one whose buyer chooses the price, and not
 * another bundle.
 *
 * What a buyer gets is decided when they pay. The list is written onto the
 * checkout itself (bundleMeta), so a creator who changes the bundle later
 * changes it for the next buyer, and everyone who already bought keeps what
 * they paid for.
 *
 * The line a store shows — "$120 of products for $49" — is worked out from
 * the included products' prices as they are now, in the store's currency,
 * and it is shown only when it is true: when the products on their own add
 * up to more than the bundle costs.
 *
 * Pure, so the studio, the store and the server apply the same rules.
 */
import type { Listing } from "@/lib/store";
import { formatMoney } from "@/lib/money";

/** The fewest products a bundle may hold: one would just be the product. */
export const MIN_BUNDLE_ITEMS = 2;
/** The most. Enough for a creator's whole shelf of guides; short enough to read on a phone. */
export const MAX_BUNDLE_ITEMS = 20;

/** What a product id may look like: every id this site has ever made fits. */
const SAFE_ID = /^[A-Za-z0-9_-]{1,64}$/;

/**
 * A bundle's list as it was stored, or null for an ordinary product. Ids are
 * kept once each, in order; a list that is not a list of ids reads as none.
 */
export function parseBundleItems(raw: unknown): string[] | null {
  if (!Array.isArray(raw)) return null;
  const out: string[] = [];
  for (const id of raw) {
    if (typeof id !== "string" || !SAFE_ID.test(id) || out.includes(id)) continue;
    out.push(id);
    if (out.length >= MAX_BUNDLE_ITEMS) break;
  }
  return out.length ? out : null;
}

/** Whether this product is a bundle. */
export function isBundle(product: Pick<Listing, "bundle">): boolean {
  return Array.isArray(product.bundle) && product.bundle.length > 0;
}

/**
 * Whether a product can go into a bundle: a one-off paid product with one
 * price that hands over something whole — a file, a link, or a course with
 * at least one lesson. A draft can: selling something only as part of a
 * bundle is a reason to keep it off the store.
 */
export function canBeInBundle(product: Listing): boolean {
  if (product.priceCents <= 0) return false;
  if (product.recurring !== null || product.call !== null || isBundle(product)) return false;
  if (product.options.length > 0 || product.pwyw !== null) return false;
  if (product.course) return product.course.lessons > 0;
  return product.file !== null || product.link !== null;
}

/** Why an included product cannot be in a bundle, in words for the studio. */
export function whyNotInBundle(product: Listing): string | null {
  // Only a checkout of its own counts a sale against a limited number.
  if (canBeInBundle(product)) return product.stock !== null ? "It has a limited number for sale" : null;
  if (product.priceCents <= 0) return "It is free";
  if (product.recurring) return "It is a membership";
  if (product.call) return "It is a call";
  if (isBundle(product)) return "It is a bundle";
  if (product.options.length > 0) return "It has several prices";
  if (product.pwyw) return "Its buyers choose the price";
  if (product.course) return "The course has no lessons yet";
  return "It has nothing to hand over yet";
}

/**
 * Whether a product can itself be made a bundle: a one-off paid product with
 * one price and nothing of its own to hand over. A file, a link or lessons
 * of its own would be one more thing the buyer is promised; take them off
 * first, as for a call or a course.
 */
export type OwnerProblem = "free" | "recurring" | "call" | "course" | "delivery" | "options" | "pwyw";

export function bundleOwnerProblem(product: Listing): OwnerProblem | null {
  if (product.priceCents <= 0) return "free";
  if (product.recurring) return "recurring";
  if (product.call) return "call";
  if (product.course) return "course";
  if (product.file || product.link) return "delivery";
  if (product.options.length > 0) return "options";
  if (product.pwyw) return "pwyw";
  return null;
}

export type BundleProblem = OwnerProblem | "count" | "self" | "unknown" | "kind" | "pick";

/**
 * Why this list cannot be saved on this product, or null when it can.
 * `listings` holds the listed products as the store has them now.
 */
export function bundleProblem(items: string[], listings: Listing[], owner: Listing): BundleProblem | null {
  return bundleOwnerProblem(owner) ?? itemsProblem(items, listings, owner.id);
}

/** Why a list cannot be what a bundle holds, whatever the bundle; `ownerId` is left out of it. */
export function itemsProblem(items: string[], listings: Listing[], ownerId = ""): "count" | "self" | "unknown" | "kind" | null {
  if (new Set(items).size !== items.length) return "count";
  if (items.length < MIN_BUNDLE_ITEMS || items.length > MAX_BUNDLE_ITEMS) return "count";
  for (const id of items) {
    if (id === ownerId) return "self";
    const found = listings.find((p) => p.id === id);
    if (!found) return "unknown";
    if (!canBeInBundle(found)) return "kind";
    // A sale inside a bundle is not counted against a limited number.
    if (found.stock !== null) return "kind";
  }
  return null;
}

/**
 * What a bundle holds that can be handed over right now, in its order: the
 * products still listed and still whole. What was removed or changed since
 * is left out rather than sold.
 */
export function deliverableItems(bundle: Pick<Listing, "bundle">, listings: Listing[]): Listing[] {
  const byId = new Map(listings.map((p) => [p.id, p]));
  return (bundle.bundle ?? []).map((id) => byId.get(id)).filter((p): p is Listing => Boolean(p && canBeInBundle(p)));
}

// ---- Chosen by the buyer -------------------------------------------------------

/**
 * A bundle the buyer builds (added 10 October 2026): "any 3 of these 8 for
 * $49". The creator lists the products to choose from, as for any bundle,
 * and says how many each buyer chooses; the buyer ticks that many, and those
 * are written onto their checkout (bundleMeta) and handed over exactly as a
 * bundle's always are. Every rule above still holds for the list.
 *
 * Because the buyer has to choose, it is bought from its own page or card
 * only: never in a box at checkout, as an offer after paying, as a gift, for
 * several people, or through PayPal.
 */

/** The fewest a buyer may be asked to choose. */
export const MIN_PICK = 2;

/** How many a buyer chooses, as stored: a whole number from MIN_PICK up, or null for "all of them". */
export function parsePick(raw: unknown): number | null {
  return typeof raw === "number" && Number.isInteger(raw) && raw >= MIN_PICK && raw < MAX_BUNDLE_ITEMS ? raw : null;
}

/** Whether a bundle has its buyers choose. */
export function picks(product: Pick<Listing, "bundle"> & { pick?: number | null }): number | null {
  return isBundle(product) && product.pick ? product.pick : null;
}

/** Why `pick` cannot be asked of a list of `count` products: fewer to choose from than to choose. */
export function pickProblem(pick: number | null, count: number): "pick" | null {
  if (pick === null) return null;
  return pick >= MIN_PICK && pick < count ? null : "pick";
}

/** Whether a bundle can be sold right now: enough to hand over, and, when buyers choose, enough to choose from. */
export function bundleReady(product: Pick<Listing, "bundle"> & { pick?: number | null }, deliverable: number): boolean {
  return deliverable >= Math.max(MIN_BUNDLE_ITEMS, picks(product) ?? 0);
}

/**
 * The products a buyer chose, from what the bundle can hand over now, in the
 * bundle's own order: exactly `pick` different ones, each from the list, or
 * null when the choice is anything else.
 */
export function chosenItems(pool: Listing[], picked: string[], pick: number): Listing[] | null {
  const wanted = new Set(picked.filter((id) => SAFE_ID.test(id)));
  if (wanted.size !== pick || picked.length !== pick) return null;
  const chosen = pool.filter((p) => wanted.has(p.id));
  return chosen.length === pick ? chosen : null;
}

/** What the included products cost on their own, together, in the store's smallest unit. */
export function worthOf(items: Pick<Listing, "priceCents">[]): number {
  return items.reduce((sum, item) => sum + Math.max(0, item.priceCents), 0);
}

/**
 * "$120 of products for $49", in the store's currency — only when the
 * products on their own do cost more than the bundle. Otherwise null, and
 * nothing is claimed.
 */
export function worthWords(items: Pick<Listing, "priceCents">[], priceCents: number, currency: string): string | null {
  const worth = worthOf(items);
  if (worth <= priceCents || items.length < MIN_BUNDLE_ITEMS) return null;
  return `${formatMoney(worth, currency)} of products for ${formatMoney(priceCents, currency)}`;
}

// ---- On the checkout ---------------------------------------------------------

/**
 * Stripe keeps up to 500 characters in one metadata value. Twenty ids of the
 * longest kind need more, so a list is written across up to three keys:
 * "bundle", "bundle_2" and "bundle_3" (and "bump_bundle"… for the product
 * ticked at checkout, "bump2_bundle"… and "bump3_bundle"… for the second and
 * third box).
 */
const META_VALUE = 480;
const META_PARTS = 3;

/**
 * The keys a checkout names the products ticked at checkout under, one per
 * box, in the product's order (lib/product-extras.ts, MAX_BUMPS). The first
 * is the key every order made when a product had one box carries, so those
 * read the same as before. Each has its list under `<key>_bundle` when it is
 * a bundle, and its price and affiliate share under `<key>_cents` and
 * `<key>_rate`.
 */
export const BUMP_KEYS = ["bump", "bump2", "bump3"] as const;
export type BumpKey = (typeof BUMP_KEYS)[number];

export type BundleSlot = "bundle" | `${BumpKey}_bundle`;

/** The products ticked at checkout, by the key each is under, in order. */
export function bumpsFromMeta(meta: Record<string, string | undefined> | null | undefined): { key: BumpKey; id: string }[] {
  if (!meta) return [];
  const out: { key: BumpKey; id: string }[] = [];
  for (const key of BUMP_KEYS) {
    const id = meta[key];
    if (typeof id === "string" && SAFE_ID.test(id) && !out.some((b) => b.id === id)) out.push({ key, id });
  }
  return out;
}

/** The metadata entries that carry one list, by the key they go under. */
export function bundleMeta(slot: BundleSlot, ids: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  const parts: string[] = [];
  let current = "";
  for (const id of ids.filter((x) => SAFE_ID.test(x)).slice(0, MAX_BUNDLE_ITEMS)) {
    const next = current ? `${current},${id}` : id;
    if (next.length > META_VALUE) {
      parts.push(current);
      current = id;
    } else current = next;
  }
  if (current) parts.push(current);
  parts.slice(0, META_PARTS).forEach((part, i) => {
    out[i === 0 ? slot : `${slot}_${i + 1}`] = part;
  });
  return out;
}

/** The list a checkout carries under one key, as it was written; [] for none. */
export function bundleFromMeta(meta: Record<string, string | undefined> | null | undefined, slot: BundleSlot): string[] {
  if (!meta) return [];
  const out: string[] = [];
  for (let i = 0; i < META_PARTS; i += 1) {
    const raw = meta[i === 0 ? slot : `${slot}_${i + 1}`];
    if (typeof raw !== "string" || !raw) break;
    for (const id of raw.split(",")) {
      if (SAFE_ID.test(id) && !out.includes(id)) out.push(id);
    }
  }
  return out.slice(0, MAX_BUNDLE_ITEMS);
}

/** The most products a creator's extra for one affiliate's link adds to an order (lib/affiliate-extra-rules.ts). */
export const MAX_AFFILIATE_EXTRAS = 3;

/**
 * The extras a checkout carries under `aff_extra`, as written; [] for none
 * (630 [HN6](6)). Kept here, beside the other lists a checkout carries, so the
 * readers of deliveredIds need nothing else.
 */
export function extraFromMeta(meta: Record<string, string | undefined> | null | undefined): string[] {
  const raw = meta?.aff_extra;
  if (typeof raw !== "string" || !raw) return [];
  return [...new Set(raw.split(",").filter((id) => SAFE_ID.test(id)))].slice(0, MAX_AFFILIATE_EXTRAS);
}

/**
 * Every product a checkout hands over, by id: the product bought, the one
 * ticked at checkout, and every product of either when it is a bundle, each
 * once. What refunds, reviews, keys, the community's door and courses read.
 * None for a gift, whose buyer is not its owner, for a purchase for several
 * people, whose places are handed out from its own link, or for a pre-order.
 */
export function deliveredIds(meta: Record<string, string | undefined> | null | undefined): string[] {
  // A gift hands over nothing to whoever paid: it is the recipient's
  // (lib/gifts.ts), written down under their own address.
  if (meta?.gift) return [];
  // Bought for several: each place is written down under the address that
  // took it (lib/group-buy.ts), the buyer's own included.
  if (meta?.group) return [];
  // A pre-order hands over nothing until the product comes out; then it is
  // written down under its buyer's address, as a gift is (lib/preorders.ts).
  if (meta?.preorder) return [];
  const added = bumpsFromMeta(meta);
  const ids = [
    meta?.product,
    ...added.map((b) => b.id),
    ...bundleFromMeta(meta, "bundle"),
    ...added.flatMap((b) => bundleFromMeta(meta, `${b.key}_bundle`)),
    // The creator's extra for buying through one affiliate's link (630 [HN6](6),
    // lib/affiliate-extra-rules.ts), handed over and taken back with the order.
    ...extraFromMeta(meta),
  ];
  const out: string[] = [];
  for (const id of ids) if (typeof id === "string" && id && !out.includes(id)) out.push(id);
  return out;
}

lib/api-guard.ts.content:
/**
 * The door every /api/v1 request goes through.
 *
 * A key from the Authorization header, its store by the store's permanent id,
 * and a limit per key. Nothing else is read from the request to decide whose
 * data is returned: there is no store name, id or address in any URL here,
 * so there is nothing to change to reach another store's data. The key alone
 * says whose it is.
 *
 * No CORS headers, on purpose. These are keys for a creator's own server,
 * Zapier or Make — a key in a web page's script is a key anybody who opens the
 * page can copy, and a browser refusing the request is the kinder way to learn
 * that.
 */
import { type AgentScope, type PauseWhy, keyFromHeader, resolveKey } from "@/lib/api-keys";
import { agentMay } from "@/lib/api-key-rules";
import { storeForId, type Store } from "@/lib/store";
import { BodyTooLarge, limited, withinLimit } from "@/lib/request-guard";
import { giveAllowance, takeAllowance } from "@/lib/store-allowance";
import { reservePaidResourceWindow } from "@/lib/contract-resource-window";
import { API_READ_PAUSED_WORDS, API_WRITE_PAUSED_WORDS, integrationPauseWord } from "@/lib/integration-pause";

/** Requests one key may make in a minute. Generous for a sync, a wall for a runaway loop. */
export const API_RATE = 120;

const headers = { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" };

/** What a paused key's request is told, by why it is paused (lib/api-keys.ts PauseWhy): who can turn it back on, if anybody. */
export const KEY_PAUSED_WORDS: Readonly<Record<PauseWhy, string>> = {
  rule: "This key is paused: the store's team now logs in with a second step, and the key was made without one. Whoever made it can turn it back on under API keys in the studio, after logging in with a passkey or an authenticator app's code.",
  left: "This key is paused for good: it was made by someone who is no longer on the store's team. The store's owner can revoke it under API keys in the studio and make a new one.",
  role: "This key is paused: the role of the person who made it no longer allows it. The store's owner can turn it back on under API keys in the studio.",
  unmatched: "This key is paused: it could not be linked to anyone on the store's team, most likely because the server's secret changed. The store's owner can check whose key it is under API keys in the studio (its name and when it was last used help), then turn it back on for that person, or revoke it.",
  unknown: "This key is refused for now: its state on the store could not be read. Try again in a moment. If this keeps happening, the store's owner can revoke it under API keys in the studio and make a new one.",
  unrecorded: "This key is paused: nobody is recorded as its maker (keys made before November 4, 2026), and after a change on the store's team (someone leaving, a role changed, or two-step login asked of everyone) such a key waits for the owner. The store's owner can turn it back on under API keys in the studio.",
};

export function apiError(status: number, error: string, message: string, extra: Record<string, string> = {}): Response {
  return Response.json({ error, message }, { status, headers: { ...headers, ...extra } });
}

export function apiOk(body: unknown): Response {
  return Response.json(body, { headers });
}

/** The store this request may read, or the response that refuses it. */
export async function apiStore(request: Request): Promise<Store | Response> {
  const found = await apiKeyed(request, "read");
  return found instanceof Response ? found : found.store;
}

/**
 * The store this request may change, and the key it came with, or the
 * response that refuses it: a key made to read only is refused here, with
 * the way to make one that writes.
 */
export async function apiWriter(request: Request): Promise<{ store: Store; keyId: string } | Response> {
  const found = await apiKeyed(request, "write");
  if (found instanceof Response) return found;
  if (!found.write) {
    return readOnly();
  }
  return { store: found.store, keyId: found.keyId };
}

/**
 * 232 [CA1] unit 4c: the store a write that adds or changes may change, its
 * key and the request's body, or the response that refuses it. While the
 * plan's renewal is unpaid or a payment for it is disputed, the write is
 * refused with its sentence before any of the month is taken; `adds` says
 * whether this body adds anything (left out: every body does), so a body
 * that only takes something away (labels removed) still goes through. The
 * body is read only when `adds` needs it.
 */
export async function apiAdder(
  request: Request,
  adds?: (body: Record<string, unknown>) => boolean,
): Promise<{ store: Store; keyId: string; body: Record<string, unknown> } | Response> {
  let body: Record<string, unknown> | null = null;
  const found = await apiKeyed(request, "write", async (store) => {
    const paused = integrationPauseWord(store);
    if (!paused) return null;
    if (adds) {
      const read = await readApiBody(request);
      if (read instanceof Response) return read;
      body = read;
      if (!adds(read)) return null;
    }
    return apiError(409, paused, API_WRITE_PAUSED_WORDS[paused]);
  });
  if (found instanceof Response) return found;
  if (!found.write) return readOnly();
  if (!body) {
    const read = await readApiBody(request);
    if (read instanceof Response) return read;
    body = read;
  }
  return { store: found.store, keyId: found.keyId, body };
}

const readOnly = () => apiError(403, "read_only", "This key reads only. Make a key that can also write, in your studio under API keys.");

/**
 * 631 [AA1] (c): the store an AI agent may prepare a change for, with its key
 * and that key's scope, or the response that refuses it. `need` is the kind
 * of change: "draft" (the creator may confirm several at once) or "execute"
 * (it reaches people or cannot be taken back, so it is confirmed alone). A
 * key made without an agent scope is refused, whatever else it may do: a key
 * that writes leads is not a key that prepares changes. While the plan's
 * renewal is unpaid or a payment for it is disputed, preparing waits like any
 * write, before any of the month is taken. Nothing here carries a change out.
 */
export async function apiAgent(
  request: Request,
  need: "draft" | "execute",
): Promise<{ store: Store; keyId: string; agent: AgentScope } | Response> {
  const found = await apiKeyed(request, need, async (store) => {
    const paused = integrationPauseWord(store);
    return paused ? apiError(409, paused, API_WRITE_PAUSED_WORDS[paused]) : null;
  });
  if (found instanceof Response) return found;
  if (!agentMay(found.agent, need)) {
    return need === "draft"
      ? apiError(403, "cannot_prepare", "This key cannot prepare changes for you to confirm.")
      : apiError(403, "cannot_prepare_execute", "This key cannot prepare emails or other changes that reach people.");
  }
  return { store: found.store, keyId: found.keyId, agent: found.agent };
}

async function apiKeyed(
  request: Request,
  purpose: "read" | "write" | "draft" | "execute",
  hold?: (store: Store) => Promise<Response | null>,
): Promise<{ store: Store; keyId: string; write: boolean; agent: AgentScope } | Response> {
  const presented = keyFromHeader(request.headers.get("authorization"));
  const unauthorized = () =>
    apiError(401, "unauthorized", "Send your API key as: Authorization: Bearer nl_live_…", {
      "WWW-Authenticate": 'Bearer realm="Marktmorgen API"',
    });
  if (!presented) return unauthorized();
  const found = await resolveKey(presented);
  // Missing, malformed, unknown and revoked all get the same answer, so the
  // API cannot be used to learn which keys ever existed.
  if (!found) return unauthorized();
  // Paused by the team's two-step rule (owner C3-100, lib/api-key-pause.ts):
  // the key is real and kept, so its holder is told why and what to do.
  if (found.paused) return apiError(403, "key_paused", KEY_PAUSED_WORDS[found.why ?? "rule"]);
  if (!(await withinLimit("api", found.id, API_RATE, 60))) {
    return apiError(429, "rate_limited", `At most ${API_RATE} requests a minute per key. Try again in a minute.`, { "Retry-After": "60" });
  }
  const store = await storeForId(found.sid);
  if (!store) return unauthorized();
  // 232 [CA1] unit 4b4c: while the plan's renewal is unpaid or a payment for it
  // is disputed, reads wait, before any of the month is taken or Stripe is read.
  if (purpose === "read") {
    const paused = integrationPauseWord(store);
    if (paused) return apiError(409, paused, API_READ_PAUSED_WORDS[paused]);
  }
  // 232 [CA1] unit 4c: a write that adds or changes waits the same way, for a
  // key that may write (a read-only key still hears it reads only).
  // An agent's preparation waits the same way, for a key that may prepare it.
  const may = purpose === "write" ? found.write : purpose === "draft" || purpose === "execute" ? agentMay(found.agent, purpose) : true;
  if (hold && may) {
    const held = await hold(store);
    if (held) return held;
  }
  // Read-only API/MCP work, and an agent's preparation of a change (it reads
  // the store and writes a proposal), need their paid resource month (Claude 5
  // on #1856, CX72). Writing includes access revocation and needs its own
  // retained-cleanup classification.
  if (purpose !== "write" && store.period?.funded === true && !(await reservePaidResourceWindow(store))) {
    return apiError(429, "unavailable", "The store could not answer just now. Try again in a moment.");
  }
  // Each request is one of the store's window (lib/store-allowance-rules.ts), taken before any work.
  const taken = await takeAllowance(store, "api");
  if (!taken.ok) return apiError(429, taken.reason === "used" ? "monthly_limit" : taken.reason === "pool" ? "no_place" : "unavailable", taken.message);
  return { store, keyId: found.id, write: found.write, agent: found.agent };
}

const count = (n: number) => n.toLocaleString("en-US");

/**
 * Takes `more` of the store's API requests, beyond the one the request already
 * took at the door, before a reading that costs more than one request
 * (lib/api-read-rules.ts): null when taken, or when there is nothing more to
 * take; else the refusal to send as it is, and nothing more is read. Refused,
 * none of them is kept (lib/store-allowance.ts gives back what did not fit).
 * A count that is not one (a size that could not be read) is refused too.
 *
 * `taken` is what this same reading already took beyond the door, when this
 * is a later step of it (a kept copy gone since it was measured, a page that
 * came back larger than was set aside): the refusal then says the whole count
 * and that what was read so far is not shown, and what was already taken
 * stays counted. A first step passes nothing.
 */
export async function takeMoreApi(store: Store, more: number, taken = 0): Promise<Response | null> {
  if (more === 0) return null;
  if (!Number.isSafeInteger(more) || more < 0) return apiError(502, "unavailable", "This could not be read just now. Try again in a moment.");
  const took = await takeAllowance(store, "api", more);
  if (took.ok) return null;
  if (took.reason === "used") {
    return apiError(
      429,
      "monthly_limit",
      taken > 0
        ? `This read needs ${count(1 + taken + more)} of your store's API requests in all, more than your store has left, so what it read so far is not shown; the ${count(1 + taken)} it already took stay counted.`
        : `This read takes ${count(more + 1)} of your store's API requests, more than your store has left, so nothing was read.`,
    );
  }
  return apiError(429, took.reason === "pool" ? "no_place" : "unavailable", took.message);
}

/** Settles a reading set aside with holdMoreApi at the further requests it really took (lib/api-read-rules.ts, settledUnits): null when settled, else the refusal. */
export type Settle = (actual: number) => Promise<Response | null>;

/**
 * Sets `most` of the store's API requests aside, beyond the door's, before a
 * reading whose size is known only once it is read (a page of the list or of
 * the members, the kept copy of the numbers, what buyers bought next): refused
 * with nothing read when they are not left. Then `settle(actual)` gives back
 * what the reading did not need or, when it needed more than was set aside,
 * takes the rest (refused with takeMoreApi's later-step words, nothing shown).
 * So the store pays what was read, and nothing is read that the requests it
 * has left could not pay at its most. A failure between the two (a database
 * or Stripe error, a crash) gives nothing back: what was set aside stays
 * counted, by design, because the work may have been done.
 */
export async function holdMoreApi(store: Store, most: number): Promise<Response | Settle> {
  if (!Number.isSafeInteger(most) || most < 0) return apiError(502, "unavailable", "This could not be read just now. Try again in a moment.");
  const now = Date.now();
  if (most > 0) {
    const took = await takeAllowance(store, "api", most, now);
    if (!took.ok) {
      return took.reason === "used"
        ? apiError(429, "monthly_limit", `This read may take up to ${count(most + 1)} of your store's API requests, more than your store has left, so nothing was read.`)
        : apiError(429, took.reason === "pool" ? "no_place" : "unavailable", took.message);
    }
  }
  return async (actual: number) => {
    // A measure that is not a count keeps all that was set aside, and nothing is shown.
    if (!Number.isSafeInteger(actual) || actual < 0) return apiError(502, "unavailable", "This could not be read just now. Try again in a moment.");
    if (actual < most) await giveAllowance(store, "api", most - actual, now);
    return actual > most ? takeMoreApi(store, actual - most, most) : null;
  };
}

/** Most a write request's body may weigh. */
const MAX_BODY_BYTES = 4_000;

/** A write request's JSON body, or the response that refuses it. */
export async function readApiBody(request: Request): Promise<Record<string, unknown> | Response> {
  const bad = () => apiError(400, "invalid", "Send a JSON object as the body, with Content-Type: application/json.");
  if (Number(request.headers.get("content-length") ?? "0") > MAX_BODY_BYTES) return apiError(413, "too_large", `The body may be up to ${MAX_BODY_BYTES} bytes.`);
  try {
    // Read only as far as the ceiling, whether or not a length was declared (docs/security-audit-2026-10-18.md, MM-SA-10).
    const text = await (await limited(request, MAX_BODY_BYTES)).text();
    const parsed: unknown = JSON.parse(text);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? (parsed as Record<string, unknown>) : bad();
  } catch (error) {
    if (error instanceof BodyTooLarge) return apiError(413, "too_large", `The body may be up to ${MAX_BODY_BYTES} bytes.`);
    return bad();
  }
}

lib/redis-reply.ts.content:
/**
 * Reading a Redis reply only in its exact shape (audit SG2, CX-123 rule 24).
 *
 * A reply that is missing, cut short or of another shape is not an empty
 * set, a zero or a success: it is unknown, and what depends on it fails
 * closed. These answer null for anything but the exact shape, and the
 * caller decides what failing closed means there (keep what it would have
 * deleted, refuse, or say it could not read).
 *
 * Node's isProxy (node:util) is read at run time through
 * process.getBuiltinModule (Node 20.16+/22.3+; CI and the server run Node 22/24)
 * rather than imported, so a client bundle that reaches this file through a
 * shared module (components/blog-body.tsx -> lib/store-blog.ts) still builds: in
 * a browser there is no Redis reply to read, and no Proxy check is needed there.
 */
type ProxyCheck = (value: unknown) => boolean;
/**
 * The Proxy check for where this runs: Node's own when it can be read; in a browser (no Redis reply ever reaches
 * there) none is needed; on a server without it (a Node older than 20.16/22.3), every reply counts as a Proxy, so
 * each read fails closed as unknown and says so once, never quietly accepting a reply whose traps would run
 * (Revisor 1 on #2822).
 */
export function proxyCheckFor(host: { getBuiltinModule?: (id: string) => unknown } | undefined, browser: boolean): ProxyCheck {
  const util = host?.getBuiltinModule?.("node:util") as { types?: { isProxy?: unknown } } | undefined;
  const check = util?.types?.isProxy;
  if (typeof check === "function") return check as ProxyCheck;
  if (browser) return () => false;
  let told = false;
  return () => {
    if (!told) {
      told = true;
      console.error("node:util isProxy is not available on this server; every Redis reply is read as unknown (Node 20.16+/22.3+ needed)");
    }
    return true;
  };
}
const isProxy: ProxyCheck = proxyCheckFor(
  typeof process === "undefined" ? undefined : (process as { getBuiltinModule?: (id: string) => unknown }),
  typeof window !== "undefined",
);

/**
 * A list's own data slots, as a fresh plain list, with no code of the reply
 * run to read it. A Proxy is refused before any reflection, so none of its
 * traps runs (Codex S on #2672; the check Codex E2 accepted in
 * lib/stats-notes.ts). A plain or frozen array has no executable envelope
 * left: its length and each slot are read as own descriptors, so a slot that
 * is missing (a hole), inherited from a prototype or a getter is not a reply,
 * and the whole answer is null. With `expected`, the length must be exactly it.
 */
function ownSlots(reply: unknown, expected?: number): unknown[] | null {
  if (isProxy(reply) || !Array.isArray(reply)) return null;
  const length = Object.getOwnPropertyDescriptor(reply, "length");
  if (!length || !Object.hasOwn(length, "value")) return null;
  const count: unknown = length.value;
  if (typeof count !== "number" || !Number.isSafeInteger(count) || count < 0) return null;
  if (expected !== undefined && count !== expected) return null;
  const out: unknown[] = [];
  for (let i = 0; i < count; i += 1) {
    const slot = Object.getOwnPropertyDescriptor(reply, String(i));
    if (!slot || !Object.hasOwn(slot, "value")) return null;
    out.push(slot.value);
  }
  return out;
}

/**
 * A list of strings (SMEMBERS, LRANGE, ZRANGEBYSCORE, HGETALL): exactly that,
 * as a fresh list read from the reply's own data slots, or null. A Proxy, a
 * hole, an inherited member or a getter is refused, and nothing of the reply
 * is run (Codex S on #2672).
 */
export function stringList(reply: unknown): string[] | null {
  const slots = ownSlots(reply);
  if (!slots) return null;
  for (const member of slots) if (typeof member !== "string") return null;
  return slots as string[];
}

/**
 * A list's own data slots, whatever each holds, as a fresh plain list, or null for anything that is not a plain list
 * (a Proxy, a hole, an inherited slot or a getter). For a reply whose members are read one by one, so a member that
 * cannot be read is told apart from the ones that can; nothing of the reply is run.
 */
export function listSlots(reply: unknown): unknown[] | null {
  return ownSlots(reply);
}

/** A count (DEL, EXISTS, SCARD, HLEN, an EVAL that answers one): a whole number from zero up, or null. */
export function countOf(reply: unknown): number | null {
  return typeof reply === "number" && Number.isSafeInteger(reply) && reply >= 0 ? reply : null;
}

/**
 * A pipeline's replies, only when there is exactly one for each command sent,
 * as a fresh plain list. Each reply is read from the list's own data slot:
 * a slot that is missing (a hole), inherited from a prototype or a getter is
 * not a reply, and the whole answer is null (Codex S on #2672; Codex G on #2806), so nothing
 * read later can answer differently from what was checked. A Proxy is refused
 * before any of its traps can run.
 */
export function repliesFor(replies: unknown, commands: number): unknown[] | null {
  return ownSlots(replies, commands);
}

/**
 * One page of a SCAN, SSCAN, HSCAN or ZSCAN, read exactly (rules 24 and 30, review of #2921): the pipeline's one
 * reply, a [cursor, items] pair whose cursor is a string of digits and whose items are strings; null for anything
 * else. A page that does not read is unknown: never the end of the walk ("0"), never a page with nothing on it.
 * The caller throws UnknownReplyError on null, and bounds its walk with a page ceiling past which it is unknown too.
 */
export function scanPage(replies: unknown): { next: string; items: string[] } | null {
  const reply = ownSlots(replies, 1);
  const page = reply ? ownSlots(reply[0], 2) : null;
  if (!page) return null;
  const next = page[0];
  // "", "abc", " 0" or a number is not a cursor (Codex T on #2921): it would end the walk or mislead it.
  if (typeof next !== "string" || !/^[0-9]+$/.test(next)) return null;
  const items = stringList(page[1]);
  return items ? { next, items } : null;
}

/** Thrown where a reply was not in its exact shape, so what depended on it is said as not done. */
export class UnknownReplyError extends Error {
  constructor(what: string) {
    super(`Redis answered ${what} in an unknown shape`);
    this.name = "UnknownReplyError";
  }
}
